(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/poems-0005.js"] = [{"id":"poem-212b79ebbbff6b170c5b3a31","title":"偈","author":"念禅师","dynasty":"宋","verses":["往复无际，动静一源。","含有德以还空，越无私而迥出。","昔日日，今日日，照无两明。","昔日风，今日风，鼓无两动。","昔日雨，今日雨，泽无两润。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-09433c45-1008-4de9-8cc4-febf0cae104f","tags":[]},{"id":"poem-212cbcc5738ce38c8a60a818","title":"守岁应制","author":"沈佺期","dynasty":"唐","verses":["南渡轻冰解渭桥，东方树色起招摇。","天子迎春取今夜，王公献寿用明朝。","殿上灯人争烈火，宫中侲子乱驱妖。","宜将岁酒调神药，圣祚千春万国朝。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-a3253a45-9c78-4b9f-b9ad-a07644697800","tags":[]},{"id":"poem-2142c34d81f227d9f35dd187","title":"如梦令·如梦","author":"叶祖义","dynasty":"宋","verses":["如梦。","如梦。","和尚出门相送。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-611","tags":[]},{"id":"poem-21464b824a42b0af562c8d60","title":"溪上遇雨二首 一","author":"崔道融","dynasty":"唐","verses":["回塘雨脚如缲丝，野禽不起沈鱼飞。","耕蓑钓笠取未暇，秋田有望从淋漓。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-f585e4de-95f0-45f7-a34e-7c4221b6d3d4","tags":[]},{"id":"poem-2148dd1ebbf0ff147108d563","title":"即事","author":"释居简","dynasty":"宋","verses":["竹扉半掩不须敲，掠面融风著柳梢。","燕子不知春寂寞，自衔泥补去年巢。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-7e95c6ff-27f3-4966-aa3e-077c0b8dcfa8","tags":[]},{"id":"poem-215430aa58a25c2b5c573edd","title":"伐柯","author":"佚名","dynasty":"先秦","verses":["伐柯如何？匪斧不克。取妻如何？匪媒不得。","伐柯伐柯，其则不远。我觏之子，笾豆有践。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-157","tags":[]},{"id":"poem-215a434f250c028b4cea40e1","title":"咏怀古迹五首 五","author":"杜甫","dynasty":"唐","verses":["诸葛大名垂宇宙，宗臣遗像肃清高。","三分割据纡筹策，万古云霄一羽毛。","伯仲之间见伊吕，指挥若定失萧曹。","福移汉祚难恢复，志决身歼军务劳。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-87f5949b-bdad-4b5e-b488-7015bd45cc4f","tags":["唐诗三百首","隋・唐・五代","七言律诗","怀古","议论"]},{"id":"poem-21606a653b1d739a612379b2","title":"往丹阳寻陆处士不遇","author":"皎然","dynasty":"唐","verses":["远客殊未归，我来几惆怅。","叩关一日不见人，绕屋寒花笑相向。","寒花寂寂徧荒阡，柳色萧萧愁暮蝉。","行人无数不相识，独立云阳古驿边。","凤翅山中思本寺，鱼竿村口望归船。","归船不见见寒烟，离心远水共悠然。","他日相期那可定，闲僧著处即经年。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-f8e32064-bcb3-41ca-ad12-5a40f34bb4a0","tags":[]},{"id":"poem-2161430b7e736261d3a439d9","title":"十一","author":"王梵志","dynasty":"唐","verses":["立身行孝道，有事莫为●。","（「有事」，伯三五五八、伯三七一六卷作「省事」。","）行使长无过，（「行使」，伯三六五六卷作「但使」，伯三七一六卷作「但知」，斯三三九三卷作「但能」。","）耶娘高枕眠。","。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-1ead8e10-f2bc-45fe-a978-9b826648b4d0","tags":[]},{"id":"poem-21625b8061e165f2ade8fc81","title":"品令·凤舞团团饼","author":"黄庭坚","dynasty":"宋","verses":["凤舞团团饼。","恨分破、教孤令。","金渠体净，只轮慢碾，玉尘光莹。","汤响松风，早减了、二分酒病。","味浓香永。","醉乡路、成佳镜。","恰如灯下，故人万里，归来对影。","口不能言，心下快活自省。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-770","tags":[]},{"id":"poem-2162f8e0899cbf50c3f67778","title":"春夜","author":"王安石","dynasty":"宋","verses":["金炉香烬漏声残，剪剪轻风阵阵寒。","春色恼人眠不得，月移花影上栏杆。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-春夜","tags":[]},{"id":"poem-21668f7dfa9fe3c45c716404","title":"风中琴","author":"卢仝","dynasty":"唐","verses":["五音六律十三徽，龙吟鹤响思庖羲。","一弹流水一弹月，水月风生松树枝。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-03f8a03b-c23c-49bc-8ee1-50de17d40c23","tags":[]},{"id":"poem-216ac2204ad94f7920b312da","title":"宴左山二首  其二","author":"刘跂","dynasty":"宋","verses":["行饭转北冈，如登赞公岭。","悠然竟晴日，终比城市永。","残霞澹微照，遥林耿疏影。","天空气象杳，落落见此境。","彼哉不自爱，快意烹五鼎。","来日苦大难，忘言得深领。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-4c179302-f319-4164-8831-795020925847","tags":[]},{"id":"poem-217f44a96857ee3d872f5530","title":"水旱祷","author":"苏拯","dynasty":"唐","verses":["祷祈勿告天，酒浆勿浇地。","阴阳和也无妖气，阴阳愆期乃人致。","病生心腹不自医，古屋澄潭何神祟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-3260b4ef-89e7-4942-87d7-45c7d1d6c630","tags":[]},{"id":"poem-217f8127d03a9432d532e8c3","title":"君贶环溪","author":"司马光","dynasty":"宋","verses":["地胜风埃外，门深花竹间。","波光冷于玉，溪势曲如环。","荣路回翔厌，华轩啸咏闲。","堪羞谢太傅，不复到东山。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-dcd6f171-0707-41a3-93f1-751f3afe4c66","tags":[]},{"id":"poem-21806de751bb5f64ec76ebf3","title":"里社","author":"柴元彪","dynasty":"宋","verses":["涤灶炮牲献腯肥，一巵滴酹纸钱飞。","提壶挈馌分肴酒，村北村南祭社归。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-858ff7c2-1d85-4a10-97bd-173dba341861","tags":[]},{"id":"poem-2181d6f6b4a39a407ab74e71","title":"和孟虔州闲斋即事","author":"包何","dynasty":"唐","verses":["古郡邻江岭，公庭半薜萝。","府僚闲不入，山鸟静偏过。","睥睨临花柳，栏干枕芰荷。","麦秋今欲至，君听两岐歌。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-6a323547-6881-41da-b642-fed14eca69de","tags":[]},{"id":"poem-21825bc44834ec82dd3b78c1","title":"江行无题一百首 九十五","author":"钱珝","dynasty":"唐","verses":["湖口分江水，东流独有情。","常时好风物，谁伴谢宣城。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-6ac16933-bda9-43ef-a68d-aa17cfa35bae","tags":[]},{"id":"poem-218a0202f761277c207fe752","title":"蝶恋花·谁悟月中真火冷","author":"黄裳","dynasty":"宋","verses":["谁悟月中真火冷。","能引尘缘，遂出轮迥境。","争奈多情都未醒。","九回肠断花间影。","万古兴亡闲事定。","物是人非，杳杳无音信。","问月可知谁可问。","不如且醉尊前景。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-637","tags":[]},{"id":"poem-218a7c39c6e09350f6fbaa91","title":"送李尊师玄","author":"孟郊","dynasty":"唐","verses":["口诵碧简文，身是青霞君。","头冠两片月，肩披一条云。","松骨轻自飞，鹤心高不群。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-0b75d681-74aa-4fc7-ad3c-8cda5d361266","tags":[]},{"id":"poem-218f602924bb054959d763f0","title":"祗役遇风谢湘中春色","author":"熊孺登","dynasty":"唐","verses":["水生风熟布帆新，只见公程不见春。","应被百花撩乱笑，比来天地一闲人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-7e371811-fcc1-4621-b150-a16b614468b9","tags":[]},{"id":"poem-218f8a1e3bd5cbd604abedb2","title":"暮上瞿唐峡","author":"项斯","dynasty":"唐","verses":["自古艰难地，孤舟旦暮程。","独愁空托命，省已是轻生。","有树皆相倚，无岩不倒倾。","蛟螭波数怒，鬼怪火潜明。","履道知无负，离心自要惊。","何年面骨肉，细话苦辛行。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-4042129d-6751-457e-9daf-d4622425ec33","tags":[]},{"id":"poem-21911a695d9f7b3d5dcead41","title":"又和六日四老会","author":"司马光","dynasty":"宋","verses":["萸房迎令节，菊蘂入芳筵。","华烛初长夜，清霜未冷天。","悲风咽横吹，骤雨送繁弦。","聊附邹枚客，敢希园绮贤。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-a8f67dbd-a21f-41fc-a10b-49f95bcedf2c","tags":[]},{"id":"poem-2192a439b1cd425c648f28a9","title":"郊庙歌辞 享先农乐章 舒和","author":"褚亮","dynasty":"唐","verses":["羽籥低昂文缀已，干戚蹈厉武行初。","望岁祈农神所听，延祥介福岂云虚。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-8c8af1df-4b92-4010-b723-32326a23bf82","tags":[]},{"id":"poem-2198fc5fe61e149c11c6411e","title":"灭胡","author":"王无竞","dynasty":"唐","verses":["汉军屡北丧，胡马遂南駈。","羽书夜惊急，边柝乱传呼。","鬬军却不进，关城势已孤。","黄云塞沙落，（项云「落」当作「路」。","蒋云「落」为「聚落」、「村落」之「落」。","）白刃断交衢。","朔雾围未解，凿山泉尚枯。","伏波塞后援，都尉失前途。","亭障多堕毁，金镞无金（全）[一]躯。","独有山东客，上书图灭胡。","（[一]俞云：「第二『金』是『全』之误。","」）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-90aa8a94-85d4-45bd-963f-ed0551460210","tags":[]},{"id":"poem-219eefeabd85c9d01e1f04c8","title":"和窦侍御登凉州七级浮图之作","author":"高适","dynasty":"唐","verses":["化塔屹中起，孤高宜上跻。","铁冠雄赏眺，金界宠招携。","空色在轩户，边声连鼓鼙。","天寒万里北，地豁九州西。","清兴揖才彦，峻风和端倪。","始知阳春后，具物皆筌蹄。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-1122ecf1-e7da-41c0-a35c-16a9ee1dca5f","tags":[]},{"id":"poem-21a2934316206e734a450722","title":"鸣鴈松林接待","author":"释了惠","dynasty":"宋","verses":["望见松林笑满腮，香厨岂为者僧开。","三千里外有知己，鸣鴈带书招不来。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-d16ebe93-6da1-473d-8eec-c9ebcbb246e7","tags":[]},{"id":"poem-21a2e8f5bafec6be6a189d9e","title":"同前","author":"无名氏《张协状元》","dynasty":"元","verses":["一街两岸官员，宅眷。","念奴夫妇不团圆，折散。","赶奴出去怎留连，千里远没盘缠，全取我两文钱。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2662","tags":[]},{"id":"poem-21b304ea2f48571f78ee842a","title":"奉和九月九日登慈恩寺浮图应制","author":"张景源","dynasty":"唐","verses":["飞塔凌霄起，宸游一届焉。","金壶新泛菊，宝座即披莲。","就日摇香辇，凭云出梵天。","祥氛与佳色，相伴杂𬬻烟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-f2bd99a1-8616-4140-858a-00dc5578bfa7","tags":[]},{"id":"poem-21b50fb7358df32b5dc3b217","title":"又一首","author":"独孤及","dynasty":"唐","verses":["上天垂光兮熙予以青春，今日何日兮共此良辰。","与君觥浊酒而藉落英兮，（「觥浊酒」，《唐文粹》卷九六引此序作「觵浊醪」。","）如年华之相亲。","（「如年华之相亲」，《唐文粹》作「不知年华之相亲」。","）蹇淹留以醉止。","孰云含意而未申。","（案此诗载《全唐文》卷三百八十七独孤及《仲春裴胄先宅宴集联句赋诗序》一文中。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-9434ed5e-6e69-4b43-9fe2-175c17d21ad0","tags":[]},{"id":"poem-21b7288f265a209c8a0d98ed","title":"阮郎归·西城北渚旧追随","author":"晁补之","dynasty":"宋","verses":["西城北渚旧追随。","荒台今是非。","白苹无主绿蒲迷。","停舟忆旧时。","双鸭戏，乱鸥飞。","人家烟雨西。","不成携手折芳菲。","兰绕惆怅归。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-196","tags":[]},{"id":"poem-21ba83c89817917bc73c0456","title":"杂怨 一","author":"聂夷中","dynasty":"唐","verses":["生在绮罗下，岂识渔阳道。","良人自戍来，夜夜梦中到。","渔阳万里远，近于中门限。","中门逾有时，渔阳常在眼。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-5df61077-fba8-4222-8053-1fa969c5adab","tags":[]},{"id":"poem-21bb209ef0504234937ec3af","title":"清平乐·等闲无语","author":"孙光宪","dynasty":"五代","verses":["等闲无语，春恨如何去？","终是疏狂留不住，花暗柳浓何处。","尽日目断魂飞，晚窗斜界残晖。","长恨朱门薄暮，绣鞍骢马空归。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-20","tags":[]},{"id":"poem-21c4cb9ae6c744cbb67832e6","title":"春秋战国门 又吟","author":"周昙","dynasty":"唐","verses":["马毙廐人欲就刑，百年临尽一言生。","赖逢贤相能匡救，仍免吾君播恶声。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-32c324a7-d5e8-4eb7-8ce7-59196f059bcd","tags":[]},{"id":"poem-21c76401fa3f54723d38d567","title":"力疾山下吴邨看杏花十九首 十三","author":"司空图","dynasty":"唐","verses":["徘徊自劝莫沾缨，分付年年谷口莺。","却赖无情容易别，有情早个不胜情。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-94644c7d-8ad6-477c-88c7-9bac48c97799","tags":[]},{"id":"poem-21c890e8999e4e67388ec535","title":"题墙上画相扑者","author":"谢建","dynasty":"唐","verses":["愚汉勾却白汉项，白人捉却愚人骰。","如人莫辨轮赢者，直待墙𬯎始一交。","（宋调露子《角力记》。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-a284ab45-9669-465d-a553-cbbb403dd4ff","tags":[]},{"id":"poem-21d24444e888e4357f254a55","title":"诉衷情·半钩珠箔小扬州","author":"曾觌","dynasty":"宋","verses":["半钩珠箔小扬州。","春色在重楼。","曾醉玳筵歌舞，楚梦苦难留。","情脉脉，恨悠悠。","几时休。","大都人世，会少离多，总是闲愁。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-364","tags":[]},{"id":"poem-21dc78ebe6f5ab9cd327ec4d","title":"庭竹","author":"李咸用","dynasty":"唐","verses":["嫩绿与老碧，森然庭砌中。","坐销三伏景，吟起数竿风。","叶影重还密，梢声远或通。","更期春共看，桃映小花红。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-ff4b8352-b778-47a2-908f-4213ad72151e","tags":[]},{"id":"poem-21df2a18e071e1af409a96af","title":"拾得磨墨寒山题岩赞  其二","author":"释了惠","dynasty":"宋","verses":["高兴上层巅，断崖收晚烟。","笔底两三字，人间千百篇。","心手不相知，石上墨成池。","劫石有消日，此墨无尽时。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-654aa366-1258-4df7-ae8e-bde818c34dbb","tags":[]},{"id":"poem-21f325d1c24e531a5fd3a1ba","title":"送宗密上人","author":"马戴","dynasty":"唐","verses":["门前九陌尘，石上定中身。","近放辽天鹤，曾为南岳人。","腊高松叶换，雪尽茗芽新。","一自传香后，名山愿卜邻。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-2f54aaba-e725-497f-bd5b-1d0cf1f330e1","tags":[]},{"id":"poem-21f46d3c2a589e4e57ebdad7","title":"送萧颖士赴东府得草字","author":"姚发","dynasty":"唐","verses":["天生良史笔，浪迹擅文藻。","中夏授参谋，东夷愿闻道。","行轩玩春日，饯席藉芳草。","幸得师季良，欣留箧笥宝。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-ed0a8f5b-76c8-4fc8-aa9d-4b45fe3a18eb","tags":[]},{"id":"poem-21f7676a4b7bd84a3f5bb0b0","title":"酬谢寺丞","author":"释居简","dynasty":"宋","verses":["厥月维良庆佛生，诞弥随佛际昌明。","循良既负剑南最，枉直暂丞天下平。","池草自随新句好，砌兰长傍故家荣。","当年骈俪归弹压，今日丝纶要老成。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-d2c04c03-1574-423a-9f26-7e0d5aa377bb","tags":[]},{"id":"poem-21fa7796e5ca2e01e4ab0e2a","title":"续铁𬬻步志寄平江太守","author":"释居简","dynasty":"宋","verses":["惟虚不竞实，薄俗崇虚名。","岂其乡来实，虚课今日成。","因依铁炉步，自昔闻题评。","橐籥废已久，百炼余晶晶。","大而函牛鼎，小而割鸡刃。","刀也玉如泥，锥也囊脱颖。","箕裘既失绪，族属庸振领。","区区欲就铸，水浒方接轸。","譬彼赵善战，奢抗狼虎秦。","括也读父书，言外欠发明。","奢死括驾赵，两眼空无人。","全提四十万，一窖埋长平。","括固不足道，谬甚用括者。","用名弗核实，铸错败良冶。","曩时阖闾城，呻吟满四野。","忽闻襦袴歌，一日变风雅。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-6d73b3c9-83cf-4b26-bab4-623514a091bc","tags":[]},{"id":"poem-21fac74c839f2dcd2c6c9b06","title":"隰桑","author":"佚名","dynasty":"先秦","verses":["隰桑有阿，其叶有难。既见君子，其乐如何。","隰桑有阿，其叶有沃。既见君子，云何不乐。","隰桑有阿，其叶有幽。既见君子，德音孔胶。","心乎爱矣，遐不谓矣？中心藏之，何日忘之！"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-227","tags":[]},{"id":"poem-21fb1e00f063967a502351d4","title":"祭汾阴乐章","author":"刘晃","dynasty":"唐","verses":["大君出震，有事郊禋。","斋戒既肃，馨香毕陈。","乐和礼备，候暖风春。","恭惟降福，实赖明神。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-7fe5d450-c2c0-4e86-b05c-22ff6fa7b92e","tags":[]},{"id":"poem-21fbd5445a6d937e9f4e71c6","title":"咏柳","author":"贺知章","dynasty":"唐","verses":["碧玉妆成一树高，万条垂下绿丝绦。","不知细叶谁裁出，二月春风似剪刀。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-bf4ce5bb-7a29-4b33-b8c6-55a020394ab8","tags":["春天","写景","咏物","写风","柳树","植物","风","三年级下册","咏物诗","春","小学古诗"]},{"id":"poem-21fd0c4b1a8135748fa5ad2d","title":"浣溪沙·髻子伤春慵更梳","author":"李清照","dynasty":"宋","verses":["髻子伤春慵更梳。","晚风庭院落梅初。","淡云来往月疏疏。","玉鸭熏炉闲瑞脑，朱樱斗帐掩流苏。","通犀还解辟寒无。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-725","tags":[]},{"id":"poem-2228e01a0bbfbc38cccb1201","title":"后潘","author":"释居简","dynasty":"宋","verses":["后潘水上竺仙家，领客来分竹里茶。","明日归时须记取，白苹賸采半开花。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-eb6fd8dc-181b-43a3-9661-b3b8718f8980","tags":[]},{"id":"poem-222fb002a6082dfc13c0603f","title":"对月二首 二","author":"张乔","dynasty":"唐","verses":["盈缺青冥外，东风万古吹。","何人种丹桂，不长出轮枝。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-87a6e89f-5d94-4d06-921a-539f5f057611","tags":[]},{"id":"poem-22370410d8396ee90220e342","title":"岳阳别张[祜]","author":"李涉","dynasty":"唐","verses":["十年蹭蹬为逐臣，鬓毛白尽巴江春。","鹿鸣猨啸虽寂寞，水蛟山魅多精神。","山疟困中闻有赦，死灰不望光阴借。","半夜州符唤牧童，虚教衰病生惊怕。","巫峡洞庭千里余，蛮陬水国何亲疎。","由来真宰不宰我，徒劳叹者怀吹嘘。","霸桥昔与张生别，万变桑田何处说。","龙蛇纵在没泥涂，长衢却为驽骀设。","爱君气坚风骨峭，文章真把江淹笑。","洛下诸生惧刺先，乌鸢不得齐鹰鹞。","岳阳西南湖上寺，水阁松房遍文字。","新钉张生一首诗，自余吟著皆无味。","策马前途须努力，莫学龙钟虚叹息。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-fead2d67-502b-4d65-9654-91184c8bb0e6","tags":["洞庭湖"]},{"id":"poem-223a0da4f2ae1c7dcbdeac49","title":"诫儿姪八百字","author":"范质","dynasty":"唐","verses":["（昨得谢课书，希于京秩之中更与迁转。","余以诸儿姪辈生长以来，未谙外事，艰难损益，懵然莫知，因抒古诗一章晓之。","）去年初释褐，一命列蓬丘。","（谓谢课。","）青袍春草色，白纻弃如仇。","适会龙飞庆，王泽天下流。","尔得六品阶，无乃太为优。","凡登进士第，四选升校讐。","历官十五考，叙阶与尔俦。","如何志未满，意欲陵（《纪事》「陵」作「凌」。","）云游。","若言品位卑，寄书来我求。","省之再三叹，不觉泪盈眸。","吾家本寒素，门地寡公侯。","先子有令德，乐道尚忧游。","生逢世多僻，委任信沉浮。","仕宦不喜达，吏隐同庄周。","积善有余庆，清白为贻谋。","伊余奉家训，孜孜务进修。","夙夜事勤肃，言行思悔尤。","出门择交友，防慎畏薰莸。","省躬常惧玷，恐掇庭闱羞。","童年志于学，不堕（《纪事》「堕」作「惰」。","）为箕裘。","二十中甲科，頳尾化为虬。","（二十三进士及第，今举全数。","）三十入翰苑（时三十三，），步武向瀛州。","四十登宰辅（年四十一），貂冠侍冕旒。","备位行一纪，将何助帝猷。","既非救旱雨，岂是济川舟。","天子未遐弃，日益素餐忧。","黄河润千里，草木皆浸渍。","吾宗凡九人，继踵升官次。","门内无白丁，森森朱绿紫。","鹓行洎内职，亚尹州从事。","府掾监省官，高低皆清美。","悉田侥幸升，不因资考至。","朝廷悬爵秩，命之曰公器。","才者禄及身，功者赏于世。","非才及非功。","安得专（《纪事》「专」作「沾」。","）厚利。","寒衣内府帛，饥食太仓米。","不蚕复不穑，未尝勤四体。","虽然一家荣，岂塞众人议。","颙颙十目窥，龊龊千人指。","（曾参云：「十目所视。","」古人云：「千人所指。","」言可畏。","）借问尔与吾，如何不自媿？","戒尔学立身，莫若先孝悌。","怡怡奉亲长，不敢生骄易。","战战复兢兢，造次必于是。","戒尔学干禄，莫若勤道艺。","尝闻诸格言，学而优则仕。","不患人不知，惟患学不至。","戒尔远耻辱，恭则近乎礼。","自卑而尊人，先彼而后己。","《相鼠》与《茅鸱》，宜鉴诗人剌。","（《毛诗》：「《相鼠》，刺无礼。","」《左传》：「茅鸱」，刺不恭。","）戒尔勿放旷，放旷非端士。","周孔垂名教，齐梁尚清议。","南朝称八达，千载秽青史。","戒尔勿嗜酒，狂药非佳味。","能移谨厚性。","化为凶险（《纪事》「险」作「暴」。","）类。","古今倾败者，历历皆可记。","戒尔勿多言，多言者众（《纪事》「者众」作「众所」。","）忌。","苟不慎枢机，灾危从此始。","是非毁誉间，适足为身累。","举世重交游，拟结金兰契。","忿怨容易（《纪事》「容易」作「从是」。","）生，风波当时起。","所以公君子心，汪汪淡如水。","举世好承奉，昂昂增意气。","不知承奉者，以尔为玩戏。","所以古人疾，籧篨与戚施。","举世重任侠，（《史记》：「轻死重义曰侠。","」）呼俗（《纪事》「呼俗」作「俗呼」。","）为气义。","（《纪事》「气义」作「义士」。","）为人赴急难，往往陷刑死。","所以马援书，殷勤戒诸子。","（马援告儿孙书，甚非此事。","）举世贱清素，奉身好华侈。","肥马衣轻裘，扬扬过闾里。","虽得巿童怜，还为识者鄙。","我本羁旅臣，遭逢尧舜理。","位重才不充，戚戚怀忧畏。","深渊与薄冰，蹈之唯恐坠。","尔曹非悯我，勿使著罪戾。","闭门敛踪迹，缩首避名势。","名势不久居，毕竟何足恃。","物盛必有衰，有隆还有替。","速成不坚牢，亟走多颠踬。","灼灼园中花，早发还先萎。","迟迟涧畔松，郁郁含晚翠。","赋命有疾徐，青云难力致。","寄语谢诸郎，躁进徒为耳。","（见《宋文鉴》卷十四。","以《宋诗纪事》校之。","）（此诗疑作于入宋后。","）（〖1〗《宋史》卷二四九《范质传》：「从子校书郎杲求奏迁秩，质作诗晓之。","时人传诵，以为劝戒。","」）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-37c5b00f-594e-4de1-a495-48555d8570a2","tags":["黄河"]},{"id":"poem-22469ef30ced18d25b83a09d","title":"女冠子·蕙花香也","author":"蒋捷","dynasty":"宋","verses":["蕙花香也。","雪晴池馆如画。","春风飞到，宝钗楼上，一片笙箫，琉璃光射。","而今灯漫挂。","不是暗尘明月，那时元夜。","况年来、心懒意怯，羞与蛾儿争要。","江城人悄初更打。","问繁华谁解，再向天公借。","剔残红灺。","但梦里隐隐，钿车罗帕。","吴笺银粉砑。","待把旧家风景，写成闲话。","笑绿鬟邻女，倚窗犹唱，夕阳西下。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-256","tags":["宋词三百首"]},{"id":"poem-224feffb7b4a0662a87411d9","title":"栖云阁","author":"米芾","dynasty":"宋","verses":["云出救世旱，泽浃云寻归。","入石了不见，丰功已如遗。","龙骞荐复起，抱石明幽姿。","云乎无定所，隠者当何栖。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-691f2298-ef3a-47f1-a638-1ed9229ffc10","tags":[]},{"id":"poem-2251337a9d898e438d0a01b6","title":"重阳四首 二","author":"司空图","dynasty":"唐","verses":["雨寒莫待菊花催，须怕晴空暖并开。","开却一枝开却尽，且随幽蝶更徘徊。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-4982fe25-1e34-4017-8d08-ae050f23af37","tags":[]},{"id":"poem-225582ec791c18f84080d7a6","title":"春秋战国门 豫让","author":"周昙","dynasty":"唐","verses":["门客家臣义莫俦，漆身吞炭不能休。","中行智伯思何异，国士终期国士酬。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-6179a728-52b3-45f9-884d-c97e42305dc0","tags":[]},{"id":"poem-2281e38d1b814953577dc1ed","title":"前腔","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["孩儿虽暂离，须有日回家里。","奴自有些金珠，解当充粮米。","公公婆婆休争么，教旁人道媳妇每，有甚差池，致使公婆争恁地。","婆婆，他心中爱子只望功名就；公公，他眼下无儿必是埋冤语。","难逃避，兀的不是从天降下这灾危？(合前)(外唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-4994","tags":[]},{"id":"poem-228bc9a3a17d43bfb29174aa","title":"秋日二首 一","author":"太宗皇帝","dynasty":"唐","verses":["菊散金风起，荷疎玉露圆。","将秋数行雁，离夏几林蝉。","云凝愁半岭，霞碎缬高天。","还似成都望，直见峨眉前。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-ff2b3cb0-be10-47e9-986f-3fa62c69e727","tags":[]},{"id":"poem-228ce4643bac0ae1ca317793","title":"送薛耽先辈归谒汉南","author":"薛逢","dynasty":"唐","verses":["云绕千峰驿路长，谢家联句待檀郎。","手持碧落新攀桂，月在东轩旧选床。","几日旌幢延骏马，到时冰玉动华堂。","孔门多少风流处，不遣颜回识醉乡。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-db3b36f8-1dee-48d3-9cd3-03a379d57661","tags":[]},{"id":"poem-22989b957e9c5f4554953ba0","title":"闻前王使君在泽潞居","author":"贯休","dynasty":"唐","verses":["为善无近名，窃名者得声不如心，诚哉是言也。","使君圣朝瑞，干符初刺婺。","德变人性灵，笔变人风土。","烟霞与虫鸟，和气将美雨。","千里与万里，各各来相附。","信哉有良吏，玄谶应百数。","古人古人自古人，今日又见民歌六七袴。","不幸大寇崩腾来，孤城势孤固难锢。","攀辕既不及，旌斾冲风露。","大驾已西幸，飘零何处去？","婺人空悲哀，对生祠泣沾莓苔。","忽闻暂寄河之北，兵强四面无尘埃。","唯祝銮舆早归来，用此咎繇仲虺才。","使四野雾廓，八纮镜开。","皇天无亲，长与善邻，宜哉宜哉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-2920c9a1-bdab-4435-82e1-d47c75b7df5f","tags":[]},{"id":"poem-2298a93d7e2fa0f6cdee19c7","title":"题淮南寺","author":"程颢","dynasty":"宋","verses":["南去北来休便休，白苹吹尽楚江秋。","道人不是悲秋客，一任晚山相对愁。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-題淮南寺","tags":[]},{"id":"poem-22a300d11b654901a2421eac","title":"秋朝木芙蓉","author":"李嘉祐","dynasty":"唐","verses":["水面芙蓉秋已衰，繁条到是著花时。","平明露滴垂红脸，似有朝愁暮落悲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-b51c9f56-c13f-487f-846f-90ec85b1b7ac","tags":[]},{"id":"poem-22a355508196bca40c8b613f","title":"杂曲歌辞 长干行二首 一","author":"李白","dynasty":"唐","verses":["妾发初覆额，折花门前剧。","郎骑竹马来，遶床弄青梅。","同居长干里，两小无嫌猜。","十四为君妇，羞颜尚不开。","低头向暗壁，千唤不一回。","十五始展眉，愿同尘与灰。","常存抱柱信，岂上望夫台。","十六君远行，瞿塘滟预堆。","五月不可触，猨鸣天上哀。","门前迟行迹，一一生绿苔。","苔深不能扫，落叶秋风早。","八月蝴蝶来，双飞西园草。","感此伤妾心，坐愁红颜老。","早晚下三巴，预将书报家。","相迎不道远，直至长风沙。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-1352fbf1-2c3d-459c-b4ac-061e0c6befb8","tags":["唐诗三百首"]},{"id":"poem-22a8396de9e9e54a2010af26","title":"龙虎山","author":"江万里","dynasty":"宋","verses":["凿开风月长生地，占却烟霞不老身。","虚靖当年仙去后，未知丹诀付何人。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-6f8c13cb-afb8-4b4e-9dc1-19f8bf50bb56","tags":[]},{"id":"poem-22aa06ff4f9a97edafeb5191","title":"前腔","author":"徐田臣《杀狗记》","dynasty":"元","verses":["(外)老倒无成，九十三年是他门下人。","来朝亲诣坟头去，管取劝他回心。","自古来帝君有臣，无纳谏忠言听信。","(合前)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1839","tags":[]},{"id":"poem-22aa70e6b41264a753e755b3","title":"题崔端公园林","author":"李端","dynasty":"唐","verses":["上士爱清辉，开门向翠微。","抱琴看鹤去，枕石待云归。","野坐苔生席，高眠竹挂衣。","旧山东望远，惆怅暮花飞。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-68d9ed9c-3785-4e67-9f3c-6e214f9a15a5","tags":[]},{"id":"poem-22b80095aa471c5392341e26","title":"送项平甫教授之成都","author":"陈造","dynasty":"宋","verses":["昔人石穴命西蜀，岂知桃源华胥隠石腹。","诗人昔吟蜀道难，何曾锦城风物平时看。","平时风物今犹故，井络坤维神所护。","汉官威仪二百年，斩新不受胡尘污。","蜀民日为药市游，家说追欢不说愁。","蜀人之文落中州，中州伧父缩颈羞。","吾徒向来梦游处，今日登僊送君去。","遨头上客人所敬，翰林先生士知慕。","似闻儒冠不容假，挽致邹鲁无难者。","况君笔力西汉前，亟遣人才有扬马。","锦城之乐乐未涯，绿鬓朱颜君更佳。","要奉板舆追胜日，暮万里桥朝浣花。","古今胜槩争入眼，归轩日日诗囊满。","黄鹄东飞定有书，莫靳珠玑祇推懒。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-26e4c871-dfda-4ee9-8633-08ec0d06d0f8","tags":[]},{"id":"poem-22b8cce6ad785c5c7abaa6dd","title":"次毕将叔韵寄寿阳三首  其一","author":"刘跂","dynasty":"宋","verses":["抚枕得滂湃，开轩延翠微。","乃翁故时客，何许更言归。","有兴添书滴，无心傍钓矶。","惟应一大事，策杖到禅扉。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-7a9ac666-ddb4-4c8c-b1e6-d6ba11d50f65","tags":[]},{"id":"poem-22b9679d357e6f737de42cc2","title":"醉花阴·金叶犹温香未歇","author":"毛滂","dynasty":"宋","verses":["金叶犹温香未歇。","尘定歌初彻。","暖透薄罗衣，一霎清风，人映团团月。","持杯试听留春阕。","此个情肠别。","分付与莺莺，劝取东君，停待芳菲节。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-800","tags":[]},{"id":"poem-22c23e1b0721274cf73afcea","title":"秋日雨中与萧赞善访殷舍人于翰林座中作","author":"徐铉","dynasty":"宋","verses":["野出西垣步步迟，秋光如水雨如丝。","铜龙楼下逢闲客，红药阶前访旧知。","乱点乍滋承露处，碎声因想滴蓬时。","银台钥入须归去，不惜余欢尽酒巵。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-b56cc7dd-4379-485e-89a5-c0e7fbe1c677","tags":[]},{"id":"poem-22c2c0888af48311ac00e07c","title":"江行有怀","author":"孙逖","dynasty":"唐","verses":["秋水明川路，轻舟转石圻。","霜多山橘熟，寒至浦禽稀。","飞席乘风势，回流荡日晖。","昼行疑海若，夕梦识江妃。","野霁看吴尽，天长望洛非。","不知何岁月，一似暮潮归。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-70185202-25af-412a-b5f9-5dc38903619d","tags":[]},{"id":"poem-22c458cafb6d50b9df73719e","title":"修史亭三首 二","author":"司空图","dynasty":"唐","verses":["甘心七十且酣歌，自算平生幸已多。","不似香山白居士，晚将心地著禅魔。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-d386094e-a3e1-4abe-8baa-c77bbb5fb9eb","tags":[]},{"id":"poem-22cb97086a7ecbe024bd0c6a","title":"岸花","author":"张籍","dynasty":"唐","verses":["可怜岸边树，红蘂发青条。","东风吹渡水，冲着木兰桡。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-c914d5f4-9d87-4a75-b774-0c01187b4a97","tags":[]},{"id":"poem-22d5ea042ac36b81f58f0f73","title":"早行","author":"释居简","dynasty":"宋","verses":["鹎鴂初声戒趣装，强携瘦影度重冈。","畏途政尔吴牛喘，误把残蟾作夕阳。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-79290ed0-e0a3-4be2-a99b-c32c35e55035","tags":[]},{"id":"poem-22eec7bfd824822d8981df6f","title":"同昼上人送郭秀才江南寻兄弟","author":"孟郊","dynasty":"唐","verses":["地上春色生，眼前诗彩明。","手携片宝月，言是高僧名。","溪转万曲心，水流千里声。","飞鸣向谁去，江鸿弟与兄。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-05979c1c-21bf-46ea-809e-ad7d6707eeff","tags":[]},{"id":"poem-2301780b0c0da779ae331987","title":"叶梦授送家园梅花且以绝句十五章见示次其韵  其一五","author":"李纲","dynasty":"宋","verses":["草木冻死山中村，惟有梅花解返魂。","弱植孤根傲霜霰，玉奴终不负东昏。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-093baf26-0af0-473d-8c12-b1c96e7ab068","tags":[]},{"id":"poem-230ab57324ce481367fd035b","title":"郊庙歌辞 明堂乐章 舒和","author":"褚亮","dynasty":"唐","verses":["御扆合宫承宝历，席图重馆奉明灵。","偃武修文九围泰，沈烽静柝八荒宁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-e67fd622-4eb7-4829-be03-e300a4147f52","tags":[]},{"id":"poem-230e2f2b427e14ecc6a2dd45","title":"福州歌","author":"无名氏《张协状元》","dynasty":"元","verses":["伊夺担去，我底行货，都是川里买来底。","我妻我儿，家里望消息。","(合)雪儿又飞，今夜两人在那里睡！(末)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2478","tags":[]},{"id":"poem-231e3c8d95c0226a474e934d","title":"观郡守题名","author":"王十朋","dynasty":"宋","verses":["春秋美恶不嫌同，老子韩非一传中。","壁上题名二百辈，卓然名世两三公。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-e91bf9c8-48bc-4c92-b3ac-f00a34920828","tags":[]},{"id":"poem-2320133251657b3c49489d67","title":"赤壁","author":"杜牧","dynasty":"唐","verses":["折戟沈沙铁未销，自将磨洗认前朝。","东风不与周郎便，铜雀春深鏁二乔。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-7c93c162-d424-4d91-b71b-7c9b81713b8c","tags":["隋・唐・五代","战争","八年级下册(课内)","唐诗三百首","初中古诗","七言绝句","咏史怀古","怀才不遇"]},{"id":"poem-23202f7d676b59a2ff86c5dd","title":"酬白二十二舍人早春曲江见招","author":"张籍","dynasty":"唐","verses":["曲江冰欲尽，风日已恬和。","柳色看犹浅，泉声觉渐多。","紫蒲生湿岸，青鸭戏新波。","仙掖高情客，相招共一过。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-fe3e33eb-4b54-4644-80ee-ebfc7b8f5813","tags":[]},{"id":"poem-23212480718c21128a60a5cf","title":"采桑子·庭前春逐红英尽","author":"李煜","dynasty":"五代","verses":["庭前春逐红英尽，舞态徘徊。","细雨霏微，不放双眉时暂开。","绿窗冷静芳英断，香印成灰。","可奈情怀，欲睡朦胧入梦来。"],"enabled":true,"collection":"南唐二主词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/nantang/poetrys.json#record-12","tags":[]},{"id":"poem-232430962a9caa76e2676ad0","title":"夜游宫·长记劳君送远","author":"毛滂","dynasty":"宋","verses":["长记劳君送远。","柳烟重、桃花波暖。","花外溪城望不见。","古槐边，故人稀，秋鬓晚。","我有凌霄伴。","在何处、山寒云乱。","何不随君弄清浅。","见伊时，话阳春，山数点。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-796","tags":[]},{"id":"poem-2327b216dbd14158eaa7da5a","title":"过黄石驿十许里严石间悬瀑潨射声隐然真小三峡也命仆夫剪剔翳荟为行者清心骇目之观戏成两绝  其二","author":"李纲","dynasty":"宋","verses":["终日崎岖山谷间，雨余林下水潺潺。","炎方六月不知暑，端为先生从此还。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-21c7e401-bf6e-4686-9c7f-bb9796196e6c","tags":[]},{"id":"poem-2334a65c4a8df84f2e372660","title":"宛陵寓居上沈大夫二首 一","author":"赵嘏","dynasty":"唐","verses":["满耳歌谣满眼山，宛陵城郭翠微间。","人情已觉春长在，溪户仍将水共闲。","晓色入楼红蔼蔼，夜声寻砌碧潺潺。","幽云高鸟俱无事，晚伴西风醉客还。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-7109d871-873f-4c45-a1a1-77e694702be5","tags":[]},{"id":"poem-23364849b44314efb5512c31","title":"阮郎归·杏花疏雨洒香堤","author":"纳兰性德","dynasty":"清","verses":["杏花疏雨洒香堤，高楼帘幕垂。","远山映水夕阳低，春愁压翠眉。","芳草句，碧云辞，低徊闲自思。","流莺枝上不曾啼，知君肠断时。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-71","tags":[]},{"id":"poem-233b5c413f5047e8b5a66b93","title":"惠泉","author":"李德裕","dynasty":"唐","verses":["兹泉由太洁，终不畜纤鳞。","到底清何益，含虚势自贫。","明玑难秘彩，美玉讵潜珍。","未及黄陂量，滔滔岂有津。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-5bd4807e-f20d-46e4-ab5b-530de8760a99","tags":[]},{"id":"poem-2340d4d0b1fea0f5d6b25d72","title":"斗百花·飒飒霜飘鸳瓦","author":"柳永","dynasty":"宋","verses":["飒飒霜飘鸳瓦，翠幕轻寒微透，长门深锁悄悄，满庭秋色将晚。","眼看菊蕊，重阳泪落如珠，长是淹残粉面。","鸾辂音尘远。","无险幽恨，寄情空𣨼纨扇。","应是帝王，当初怪妾辞辇。","陡顿今来，宫中第一妖娆，却道昭阳飞燕。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-54","tags":[]},{"id":"poem-234d19be9fa1a32720a2b176","title":"怀白阁道侣","author":"贯休","dynasty":"唐","verses":["寒思白阁层，石屋两三僧。","斜雪扫不尽，饥猨唤得应。","香然一字火，磬过数潭冰。","终必相寻去，孤怀久不胜。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-88626846-4a90-4f2e-8582-d2d17ed3eb29","tags":[]},{"id":"poem-23661c34e73b81321fc2c887","title":"江南行","author":"许昼","dynasty":"唐","verses":["江南萧洒地，本自与君宜。","固节还同我，虚心欲待谁。","涧泉傍借响，山木共含滋。","粉腻虫难篆，丛疎鸟易窥。","尽应逢野渡，中忽见村祠。","叶扫秋空静，根横古堑危。","影迷寒霭里，声出夜风时。","客棹深深过，人家远远移。","游边曾结念，到此数题诗。","莫恨成龙晚，成龙会有期。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-15a8ebcd-bd40-495a-8d32-f2a4730d64e5","tags":[]},{"id":"poem-2366a4ff6e07ba582ea126cb","title":"与昂上人两字继合四句初字日","author":"皎然","dynasty":"唐","verses":["有一鸟雏，凌寒独宿。","若逢云雨，两两相逐。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-dd542e66-4935-4424-a967-44b0c712f9fa","tags":[]},{"id":"poem-2374fe7f3deec95c3a639a9c","title":"谢所知","author":"李咸用","dynasty":"唐","verses":["狂歌狂舞慰风尘，心下多端亦嬾言。","早是乱离轻岁月，谁能愁悴过朝昏。","圣朝公道如长在，贱子谋身自有门。","却愧此时叨厚遇，他年何以报深恩。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-64b089aa-cb0f-401b-9aab-2067825e8b52","tags":[]},{"id":"poem-23800a6f5430ca593bce818e","title":"前腔","author":"刘唐卿《白兔记》","dynasty":"元","verses":["(旦)你后生家，说这般过头话，神鬼谁不怕？怕你五行乖。","官人，奴家有个古人，比与你听。","不记得梅岭陈辛，季宝遇着金神，此事无虚诈。","我哥哥使计策，我哥哥使计策，奴家苦恨他，怕你死在黄泉下。","他那里有鬼，去不得。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8865","tags":[]},{"id":"poem-238a52a4bd520f94ae8e8ab4","title":"句","author":"徐凝","dynasty":"唐","verses":["青山旧路在，白首醉还乡。","试到第三桥，便入千顷花。","乱后见淮水，归心忽迢遥。","乍疑鲸喷浪，忽似鹢凌风。","呀呷汀洲动，喧阗里巷空。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-a91e04b7-d45c-4a8c-9305-6ddb40a840eb","tags":[]},{"id":"poem-238b2af8af384ea20b0bb7eb","title":"哭王注","author":"司空曙","dynasty":"唐","verses":["已叹漳滨卧，何言驻隙难。","异才伤促短，诸友哭门阑。","古道松声暮，荒阡草色寒。","延陵今葬子，空使鲁人观。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-287ab2db-8089-4449-bfaa-a292facd81cf","tags":[]},{"id":"poem-23910d4458c4741559fe916e","title":"再题敬亭清越上人山房","author":"张乔","dynasty":"唐","verses":["重来访惠休，已是十年游。","向水千松老，空山一磬秋。","石窗清吹入，河汉夜光流。","久别多新作，长吟洗俗愁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-0164776b-bf22-4a59-9cc7-58364316c11b","tags":[]},{"id":"poem-239b0d251c9a05c9a570245d","title":"春光好·胭脂腻","author":"曾觌","dynasty":"宋","verses":["胭脂腻，粉光轻。","正新晴。","枝上闹红无处著，近清明。","仙娥进酒多情。","向花下、相闹盈盈。","不惜十分倾玉斝，惜凋零。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-352","tags":[]},{"id":"poem-23a4a6ee6076ee9125c1d41b","title":"初入集贤院赠李献仁","author":"崔峒","dynasty":"唐","verses":["燕代官初罢，江湖路便分。","九迁从命薄，四十幸人闻。","迹愧趋丹禁，身曾系白云。","何由返沧海，昨日谒明君。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-cfa6b0e2-6fe0-4840-bb51-b27d4d8c1afb","tags":[]},{"id":"poem-23a74f1f110a3bf215094fff","title":"夜归鹿门山歌","author":"孟浩然","dynasty":"唐","verses":["山寺钟鸣昼已昏，渔梁渡头争渡喧。","人随沙路向江村，余亦乘舟归鹿门。","鹿门月照开烟树，忽到庞公栖隐处。","岩扉松径长寂寥，惟有幽人夜来去。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-cc0e7ac3-bde4-4491-8ae5-027106709e72","tags":["唐诗三百首","写景","归隐","七言古诗"]},{"id":"poem-23b7679d9dbf3657ce1dbca0","title":"次翁士秀喜雪长咏","author":"曾协","dynasty":"宋","verses":["阴阳持权或赢缩，运气循环更剥复。","忽惊寒凛袭重裘，元是祥霙散平陆。","登山不觉屐齿折，索酒仍催葛巾漉。","萧条贫居马为二，瑟缩冻坐龟藏六。","挥毫谩诧句中眼，对案常逢食无肉。","未谋南亩五百弓，浪说朱轮三十辐。","且欣膏润入郊原，为拯黔黎出沟渎。","敢将固陋测帝心，概想生灵皆子育。","将春欲放草木叶，成岁先须天地肃。","伊余平生贪静胜，有此一廛从穆卜。","应怜此地久憔悴，端向吾庐增煜煜。","巧随高下缀琪树，任逐横斜落云屋。","尘缘顿觉一羽轻，诗句但惊翻水速。","坐令欢意荡愁思，仍遣时寒破常燠。","嵇康醉状耸危石，卫玠羸姿立修竹。","排来一一尽连璧，环立诜诜皆冠玉。","晚风徐韵仍佩环，枯木无心亦冠服。","晓连青女增粲粲，夜映金波兼穆穆。","遮藏春色失斓斑，漏泄梅花有芬馥。","掀髯一笑万事空，细读君诗倒醽醁。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-4444ba22-0e41-48d6-a453-13837d40397d","tags":[]},{"id":"poem-23b846db7c851867f1bfde73","title":"偈颂七十一首  其五二","author":"释了惠","dynasty":"宋","verses":["南山鼈鼻蛇，撺入新罗国。","吞却镇海珠，咬杀嘉州佛。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-9341258f-dc78-4e1c-b782-2aa6df095074","tags":[]},{"id":"poem-23b866ec4ceaccfcabc9dbed","title":"湖上","author":"徐元杰","dynasty":"宋","verses":["花开红树乱莺啼，草长平湖白鹭飞。","风日晴和人意好，夕阳箫鼓几船归。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-湖上","tags":[]},{"id":"poem-23bfc1cec35c8691007fa8f9","title":"商山道中","author":"张乔","dynasty":"唐","verses":["春去计秋期，长安在梦思。","多逢山好处，少值客行时。","云起争峰势，花交隐涧枝。","停骖一惆怅，应秪岭猨知。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-7d4f838a-a563-49da-822e-f3b7a7b446c1","tags":[]},{"id":"poem-23dbb69be43afdfb105e3fbd","title":"离平泉马上作","author":"李德裕","dynasty":"唐","verses":["十年紫殿掌洪钧，出入三朝一品身。","文帝宠深陪雉尾，武皇恩厚宴龙津。","黑山永破和亲虏，乌岭全阬跋扈臣。","自是功高临尽处，祸来[名]灭不由人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-bf043f37-cf30-4c39-969c-69b84fcca334","tags":[]},{"id":"poem-23e8ac4ef6bec0a6230ae0c1","title":"祝鹊","author":"王建","dynasty":"唐","verses":["神鹊神鹊好言语，行人早回多利赂。","我今庭中栽好树，与汝作巢当报汝。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-20a724d2-1075-4645-8bbd-7385f675a2dc","tags":[]},{"id":"poem-23e97a220cc89a17bfe2a17b","title":"应天长·条风布暖","author":"周邦彦","dynasty":"宋","verses":["条风布暖，霏雾弄晴，池塘遍满春色。","正是夜堂无月，沈沈暗寒食。","梁间燕，前社客。","似笑我、闭门愁寂。","乱花过，隔院芸香，满地狼藉。","长记那回时，邂逅相逢，郊外驻油壁。","又见汉宫传烛，飞烟五候宅。","青青草，迷路陌。","强带酒，细寻前迹。","市桥远，柳下人家，犹自相识。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-226","tags":["宋词三百首"]},{"id":"poem-23f2ad862e8a646f0f6fd7ea","title":"次韵王解元赁地筑屋","author":"陈造","dynasty":"宋","verses":["饥麟不落毛，士生常百忧。","何人金为埒，振客不待求。","之子磊磈胸，贮书不贮愁。","焉知奉二老，百指借岸舟。","方耐冷侵骨，未暇吟掉头。","目前帡幪托，急于温饱谋。","诗来愬穷状，读想寒飕飕。","我亦寄别巢，其拙真病鸠。","每慙乌所瞻，更羡鶑出幽。","君看沉沉者，生不谭轲丘。","可食忘嗟来，至宝忌暗投。","天地吾蘧庐，此理君信不。","为亲傥可屈，三返无宜休。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-23d88d49-38d7-4820-b260-025107bfa2aa","tags":[]},{"id":"poem-23f3a3df89c6d887989e9014","title":"水亭夜坐赋得晓雾","author":"李益","dynasty":"唐","verses":["月落寒雾起，沈思浩通川。","宿禽啭木散，山泽一苍然。","漠漠沙上路，沄沄洲外田。","犹当依远树，断续欲穷天。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-2baaeb98-3c3e-4474-a224-9e251f9f440d","tags":[]},{"id":"poem-23f5ecd6676efef46da055bb","title":"送金少卿副使归新罗","author":"张籍","dynasty":"唐","verses":["云岛茫茫天畔微，向东万里一帆飞。","久为侍子承恩重，今佐使臣衔命归。","通海便应将国信，到家犹自著朝衣。","从前此去人无数，光彩如君定是稀。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-cf87caa9-9c44-4fed-a46e-f72f5b400811","tags":[]},{"id":"poem-23ff04e6bd2eb2b8509979e3","title":"问香岩和尚（题拟）","author":"郑郎中","dynasty":"唐","verses":["来无他[辙]（彻）迹，去是非我途。","并逐猿猴尽，山川境在无？","（见《祖堂集》卷十九。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-ea64cc15-3637-43fd-9da2-245b354562b0","tags":[]},{"id":"poem-23ffbd5ee7461c69a7486013","title":"复斋奚左藏挂冠  其一","author":"释居简","dynasty":"宋","verses":["趁得身轻便挂冠，翩翩出岫白云闲。","村疎一日是两日，心广半间如万间。","聊把大门标俗子，别开荒径友佳山。","羲皇向上多余地，时对清风一破颜。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-c4a7529a-db1f-4f9f-99bf-0618535e15fd","tags":[]},{"id":"poem-2402ee39b93e75c5128c24d8","title":"破斧","author":"佚名","dynasty":"先秦","verses":["既破我斧，又缺我斨。周公东征，四国是皇。哀我人斯，亦孔之将。","既破我斧，又缺我锜。周公东征，四国是遒。哀我人斯，亦孔之嘉。","既破我斧，又缺我𨱇。周公东征，四国是遒。哀我人斯，亦孔之休。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-156","tags":[]},{"id":"poem-2405b28b58e5dc4b6a6c528c","title":"塞上","author":"张乔","dynasty":"唐","verses":["勒兵辽水边，风急卷旌旃。","绝塞寒无树，平沙势尽天。","雪晴回探骑，月落控鸣弦。","永定山河誓，南归改汉年。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-ab5a64cc-7b45-4405-ae1b-70a9c2f4a51c","tags":[]},{"id":"poem-241b8a702d72748d2c01a524","title":"石上阁","author":"无名氏","dynasty":"唐","verses":["水石引我去，南湖复东壑。","不厌随竹阴，来登石上阁。","磴道通石门，欹崖断如凿。","飞梁架峰头，夭矫虹霓若。","下视竹木杪，仰见悬泉落。","水声兼松吹，音响参众乐。","时时为雾雨，飘洒湿帘箔。","吾欲弃簪缨，于兹守寂寞。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-d827bbc7-2b82-4437-b81b-5e174dcdc134","tags":[]},{"id":"poem-242580ee1314df8d082e3d86","title":"留题宿猿洞","author":"林迥","dynasty":"宋","verses":["几年形胜晦南州，一旦声名蔼湛侯。","夜色并来三岛月，水光分破五湖秋。","荔枝影里安吟榻，红藕香中系钓舟。","金印解还天子后，诏书征起不回头。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-67a5dca6-36a2-4a07-a013-f72a131ddcbd","tags":[]},{"id":"poem-2428df0e1178ce1925a7221f","title":"元日楼前观仗 一","author":"薛逢","dynasty":"唐","verses":["千门曙色鏁寒梅，五夜疎钟晓箭催。","宝马占隄朝阙去，香车争路进名来。","天临玉几班初合，日照金鸡仗欲回。","更傍紫微瞻北斗，上林佳气满楼台。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-ef00ac2c-afcc-400c-817f-bbbe94cf5349","tags":[]},{"id":"poem-242f0d1bd98a8dcf20a9dc8a","title":"采桑子·明月多情应笑我","author":"纳兰性德","dynasty":"清","verses":["明月多情应笑我，笑我如今。","辜负春心，独自闲行独自吟。","近来怕说当时事，结遍兰襟。","月浅灯深，梦里云归何处寻。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-210","tags":[]},{"id":"poem-24484263c529dcd4ede9cc3c","title":"冬日山行过薛征君","author":"皎然","dynasty":"唐","verses":["我行倦修坂，四顾无平陆。","雨霁鸣鹰鹯，天寒聚麋鹿。","幽人访名士，家在南冈曲。","菜实萦小园，稻花遶山屋。","深居寡忧悔，胜境怡耳目。","征心尚与我，永言谢浮俗。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-8712a9d5-1263-4584-9e47-f6e0234ca731","tags":[]},{"id":"poem-244b11c9b2bf10f9ad1ca6f4","title":"常州韦郎中泛舟见饯","author":"李嘉祐","dynasty":"唐","verses":["主人冯轼贵，送客泛舟稀。","逼岸随芳草，回桡背落晖。","映花双节驻，临水伯劳飞。","醉与群公狎，春塘露冕归。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-6a1dfe28-4e40-488a-844d-5dbf5f3023e8","tags":[]},{"id":"poem-2453689ea266b4b26cb2aae6","title":"古别离二首 二","author":"李端","dynasty":"唐","verses":["与君桂阳别，令君岳阳待。","后事忽差池，前期日空在。","木落雁嗷嗷，洞庭波浪高。","远山云似盖，极浦树如毫。","朝发能几里，暮来风又起。","如何两处愁，皆在孤舟里。","昨夜天月明，长川寒且清。","菊花开欲尽，荠菜泊来生。","下江帆势速，五两遥相逐。","欲问去时人，知投何处宿。","空令猿啸时泣对湘簟竹。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-3c3ab4a7-a3d1-46bc-a942-1bb035d0e86b","tags":["洞庭湖"]},{"id":"poem-2465a443fe3b4dabe89d91e8","title":"边上送杨侍御鞫狱回","author":"马戴","dynasty":"唐","verses":["狱成冤雪晚云开，豸角威清塞鴈回。","飞将送迎遥避马，离亭不敢劝金杯。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-ba6e544d-649b-417e-92d7-fd47cb420bde","tags":[]},{"id":"poem-2474c4eb32a05bf48a4fcc0b","title":"木兰花・玉楼春·杏梁归燕双回首","author":"晏殊","dynasty":"宋","verses":["杏梁归燕双回首。","黄蜀葵花开应候。","画堂元是降生辰，玉盏更斟长命酒。","炉中百和添香兽。","帘外青蛾回舞袖。","此时红粉感恩人，拜向月宫千岁寿。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-487","tags":[]},{"id":"poem-247a9bf5434d107b76ea0804","title":"大觉高僧兰若","author":"杜甫","dynasty":"唐","verses":["巫山不见庐山远，松林兰若秋风晚。","一老犹鸣日暮钟，诸僧尚乞斋时饭。","香炉峰色隐晴湖，种杏仙家近白榆。","飞锡去年啼邑子，献花何日许门徒。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-d549304d-762c-49d7-a661-d008586a3ec1","tags":["庐山"]},{"id":"poem-247bb17527da702b4a7ca9b9","title":"裳裳者华","author":"佚名","dynasty":"先秦","verses":["裳裳者华，其叶湑兮。我觏之子，我心写兮。我心写兮，是以有誉处兮。","裳裳者华，芸其黄矣。我觏之子，维其有章矣。维其有章矣，是以有庆矣。","裳裳者华，或黄或白。我觏之子，乘其四骆。乘其四骆，六辔沃若。","左之左之，君子宜之。右之右之，君子有之。维其有之，是以似之。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-213","tags":[]},{"id":"poem-247de3c188307a4c1738ffdc","title":"览镜","author":"李崇嗣","dynasty":"唐","verses":["岁去红颜尽，愁来白发新。","今朝开镜匣，疑是别逢人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-8badfc5b-9cd3-42c7-a477-debbac0fa971","tags":[]},{"id":"poem-2484dcfd56125addf66c648b","title":"岁暮题杨录事江亭","author":"刘言史","dynasty":"唐","verses":["垂丝蜀客涕濡衣，岁尽长沙未得归。","肠断锦帆风日好，可怜桐鸟出花飞。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-52e9e9f5-c0cb-4da9-9274-f407121aa5b3","tags":[]},{"id":"poem-248820e2463ae0c93d9bd894","title":"吴状元赴阙属陈兼佥催送行语","author":"释居简","dynasty":"宋","verses":["细把前朝圣政推，娄教龙首到黄扉。","自南渡后从头数，比旧京时过眼稀。","磊砢固当为世用，风云端不与人违。","采薇只在丁山下，亟伫青鸾入翠微。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-05531a6a-4597-4dba-aed2-dc9910544b7c","tags":[]},{"id":"poem-248bfcd8e05d53686ec5a706","title":"田园四时 春 其二","author":"华镇","dynasty":"宋","verses":["细风吹尽桑黄紫，绿暗柔条添旖旎。","晚来逐伴望林梢，三星便欲当辰巳。","节过清明未云远，碎发新蚕已盈纸。","迟日融融暖有余，早晚应须候眠起。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-a3fd9978-0da0-4de7-9881-c65e2da88575","tags":[]},{"id":"poem-2493ae16cce4895177dc8dc3","title":"望江南・忆江南·归去客","author":"李纲","dynasty":"宋","verses":["归去客，迂骑过江乡。","茅店鸡声寒逗月，板桥人迹晓凝霜。","一望楚天长。","春信早，山路野梅香。","映水酒帘斜扬日，隔林渔艇静鸣榔。","杳杳下残阳。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-552","tags":[]},{"id":"poem-2493c030f4adcc16956406e2","title":"绝句","author":"张翚","dynasty":"唐","verses":["茫茫烟上水，日暮阴云飞。","孤坐正愁绪，湖南谁捣衣。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-9a7136ae-e46a-48fe-818a-3ccd4538fa2e","tags":[]},{"id":"poem-2497b1783a94ab27fce1f360","title":"台州郡治十二诗太守尤延之命赋 君子堂","author":"林宪","dynasty":"宋","verses":["古人不可逢，岂徒慕其名。","兹堂号君子，想像劳我情。","高山仰后世，作者追前声。","何处见文简，堂虚风更清。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-846184c8-cde3-431b-9f00-f2bfe8bb0e1e","tags":[]},{"id":"poem-2499549a08c970f58ca5f282","title":"天仙子·梦里藻芜青一剪","author":"纳兰性德","dynasty":"清","verses":["梦里蘼芜青一剪，玉郎经岁音书远。","暗钟明月不归来，梁上燕，轻罗扇。","好风又落桃花片。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-166","tags":[]},{"id":"poem-249f26f67a40de9fbed75670","title":"自梅趣汀行小路墝确危甚六月十一日宿金沙寺","author":"李纲","dynasty":"宋","verses":["触热过梅川，墝嶅鸟道边。","林深晴有雾，土旷昼稀烟。","略彴横溪小，篮舆碍石偏。","乱蝉鸣翳荟，叠涧泻潺湲。","闽岭虽近止，江乡犹渺然。","何曾愁瘴疠，秪是怯危颠。","借问劳行役，何如穏晏眠。","遭时正艰棘，赋分自回邅。","已幸生还里，宁辞险著鞭。","夜凉栖野寺，相对月婵娟。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-49ca17db-c86e-4465-af5e-497c8bb13ea2","tags":[]},{"id":"poem-24a3b7d3cb3efe0ea9c51049","title":"江皋晚望","author":"米芾","dynasty":"宋","verses":["柳外舣舟晚，醉余双眼醒。","水光涵一气，星彩动圆灵。","炯炯月初上，翛翛风更泠。","远山横秀碧，淡墨说吾经。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-73513dc4-8c7f-4071-9440-1d85de0a9309","tags":[]},{"id":"poem-24a9614c1cc42c32fd148d37","title":"满庭芳·疏木藏钟","author":"沈蔚","dynasty":"宋","verses":["疏木藏钟，轻烟笼角，几家帘幕灯光。","暮砧声断，空壁锁寒蜇。","入袂西风阵阵，彻醉骨、都不胜凉。","栏干外，依稀嫩竹，月色冷如霜。","仙乡。","何处是，云深路杳，不念刘郎。","但画桥流水，依旧垂杨。","要见时时便是，一向价、只作寻常。","争知道，愁肠泪眼，独自个重阳。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-975","tags":[]},{"id":"poem-24be93341f18840773db1343","title":"贡院楼北新栽小松","author":"吴武陵","dynasty":"唐","verses":["拂槛爱贞容，移根自远峰。","已曾经草没，终不任苔封。","叶少初陵雪，鳞生欲化龙。","乘春濯雨露，得地近垣墉。","逐吹香微动，含烟色渐浓。","时回日月照，为谢小山松。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-6d2278b0-2912-48e0-9b8e-c9ed7a95024e","tags":[]},{"id":"poem-24c596f64c21d3dcacd54a5f","title":"南歌子·远山愁黛眉","author":"毛熙震","dynasty":"五代","verses":["远山愁黛眉，横波慢脸明，腻香红玉茜罗轻。","深院晚堂人静，理银筝。","鬓动行云影，裙遮点屐声，娇羞爱问曲中名。","杨柳杏花时节，几多情？"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-47","tags":[]},{"id":"poem-24c88ee3c1b30365620f20ac","title":"夏日谒智远禅师","author":"孟郊","dynasty":"唐","verses":["吾师当几祖，说法云无空。","禅心三界外，宴坐天地中。","院静鬼神去，身与草木同。","因知护王国，满钵盛毒龙。","抖擞尘埃衣，谒师见真宗。","何必千万劫，瞬息去樊笼。","盛夏火为日，一堂十月风。","不得为弟子，名姓挂儒宫。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-4bf72d4e-3c82-4c98-9966-321f5014d594","tags":[]},{"id":"poem-24cb73e227a4be67707af49f","title":"句  其四","author":"李昉","dynasty":"宋","verses":["三载经纶栖凤阁，五年提笔直鳌宫。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-b247d0d7-0ee6-4ab9-8741-e1baa87e546f","tags":[]},{"id":"poem-24cf32a5fc002c7e2ad38fd1","title":"县作鹿鸣会屈致冷副端席半出诗侑一献次其韵","author":"孙介","dynasty":"宋","verses":["早叹朝阳一凤鸣，几多风奏动延英。","只今故里夸闲适，得使诸生拜老成。","妙句独先歌白雪，欢颜亲自酌乌程。","鹿鸣故事虽荣观，此段邦人分外荣。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-4cbbae9a-bc1c-46a2-a13b-7792518dfb02","tags":[]},{"id":"poem-24e5970af86c2c21d2935d51","title":"自蒲圻临湘趋岳阳道中作十首  其二","author":"李纲","dynasty":"宋","verses":["屈伸任道复何求，去国翻成汗漫游。","处世久师齐物论，摅怀聊赋畔牢愁。","霜清日薄寒光急，云惨天髙阴气浮。","袅袅西风洞庭阔，可堪更上岳阳楼。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-c20b78f7-cca0-47c2-9d64-b00d427afd62","tags":["洞庭湖","岳阳楼"]},{"id":"poem-24e6a75b7e01d5f0aeb2c98a","title":"寄钟陵光僧正颂","author":"文益","dynasty":"唐","verses":["西山巍巍兮耸碧，漳水澄澄兮练色，对现分明有何极。","（以上十首均见《景德传灯录》卷二十九。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-1006582f-7a4f-4b28-8c25-30dd4e124981","tags":[]},{"id":"poem-24e876a83838799e700cb141","title":"荷叶杯·春尽小庭花落","author":"顾敻","dynasty":"五代","verses":["春尽小庭花落，寂寞。","凭槛敛双眉，忍教成病忆佳期。","知么知，知么知。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-21","tags":[]},{"id":"poem-24ef0d11d24f978093e4b347","title":"山中春晚寄贾员外","author":"谭用之","dynasty":"宋","verses":["不随黄鹤起烟波，应笑无成返薜萝。","看尽好花春卧稳，醉残红日夜吟多。","高添雅兴松千尺，暗养清音竹数科。","珍重仙曹旧知己，往来星骑一相过。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-f0ae67b1-c51e-4c4d-a10e-f656688030fa","tags":[]},{"id":"poem-2502bca6b348fbc1524dc342","title":"风雨","author":"佚名","dynasty":"先秦","verses":["风雨凄凄，鸡鸣喈喈，既见君子。云胡不夷？","风雨潇潇，鸡鸣胶胶。既见君子，云胡不瘳？","风雨如晦，鸡鸣不已。既见君子，云胡不喜？"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-89","tags":[]},{"id":"poem-2503fc74940b4978659c67c3","title":"杨柳枝·阊门风暖落花干","author":"孙光宪","dynasty":"五代","verses":["阊门风暖落花干，飞遍江城江城雪不寒。","独有晚来临水驿，闲人多凭赤栏干。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-41","tags":[]},{"id":"poem-251647698923f8ea5dd987c8","title":"酬故人还山","author":"宋鼎","dynasty":"唐","verses":["举櫂乘春水，归山抚岁华。","碧潭宵见月，红树晚开花。","肃穆轻风度，依微隐径斜。","危亭暗松石，幽涧落云霞。","思鸟吟高树，游鱼戏浅沙。","安知余兴尽，相望紫烟赊。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-cbbe3dfd-98f0-403f-b4b4-1fd4b5d5f951","tags":[]},{"id":"poem-25173e83fdb9568fa3513d82","title":"立秋日","author":"刘言史","dynasty":"唐","verses":["商风动叶初，萧索一贫居。","老性容茶少，羸肌与簟疎。","旧醅难重漉，新菜未胜鉏。","才薄无潘兴，便便画偃庐。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-308cd53c-fc61-4dde-899e-a4db10cb3302","tags":[]},{"id":"poem-252d530d01b839c2cc7f8fbb","title":"同前","author":"无名氏《张协状元》","dynasty":"元","verses":["自从嫁它，奴办至诚，不成它负心。","一举登科有姓名，果然负奴绝耗音，万水千山奴也去寻。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2609","tags":[]},{"id":"poem-253fef485ac128ce266e388f","title":"干旄","author":"佚名","dynasty":"先秦","verses":["孑孑干旄，在浚之郊。素丝纰之，良马四之。彼姝者子，何以畀之？","孑孑干旟，在浚之都。素丝组之，良马五之。彼姝者子，何以予之？","孑孑干旌，在浚之城。素丝祝之，良马六之。彼姝者子，何以告之？"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-52","tags":[]},{"id":"poem-2548fb328286992756293f62","title":"正月","author":"佚名","dynasty":"先秦","verses":["正月繁霜，我心忧伤。民之讹言，亦孔之将。念我独兮，忧心京京。哀我小心，癙忧以痒。","父母生我，胡俾我瘉？不自我先，不自我后。好言自口，莠言自口。忧心愈愈，是以有侮。","忧心惸惸，念我无禄。民之无辜，并其臣仆。哀我人斯，于何从禄？瞻乌爰止？于谁之屋？","瞻彼中林，侯薪侯蒸。民今方殆，视天梦梦。既克有定，靡人弗胜。有皇上帝，伊谁云憎？","谓山盖卑，为冈为陵。民之讹言，宁莫之惩。召彼故老，讯之占梦。具曰予圣，谁知乌之雌雄！","谓天盖高，不敢不局。谓地盖厚，不敢不蹐。维号斯言，有伦有脊。哀今之人，胡为虺蜴？","瞻彼阪田，有菀其特。天之杌我，如不我克。彼求我则，如不我得。执我仇仇，亦不我力。","心之忧矣，如或结之。今兹之正，胡然厉矣？燎之方扬，宁或灭之？赫赫宗周，褒姒灭之！","终其永怀，又窘阴雨。其车既载，乃弃尔辅。载输尔载，将伯助予！","无弃尔辅，员于尔辐。屡顾尔仆，不输尔载。终逾绝险，曾是不意。","鱼在于沼，亦匪克乐。潜虽伏矣，亦孔之炤。忧心惨惨，念国之为虐！","彼有旨酒，又有嘉肴。洽比其邻，婚姻孔云。念我独兮，忧心殷殷。","佌佌彼有屋，蔌蔌方有谷。民今之无禄，天夭是椓。哿矣富人，哀此惸独。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-191","tags":[]},{"id":"poem-254fa76d3b65b01ea45991a8","title":"前腔","author":"刘唐卿《白兔记》","dynasty":"元","verses":["叔叔搭救，诉不尽衔冤负屈。","没来由逼写休书，将他苦苦熬煎。","天天，共乳同胞不见怜，铁石人五脏心不善。","止不住盈盈泪涟，止不住盈盈泪涟。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8854","tags":[]},{"id":"poem-25530b9cf40cf3c387aa8ee2","title":"减字木兰花·斜红翠叠","author":"向子𬤇","dynasty":"宋","verses":["斜红翠叠。","何许花神来献瑞。","粲粲裳衣。","割得天孙锦一机。","真香妙质。","不耐世间风与日。","着意遮围。","莫放春光造次归。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-113","tags":[]},{"id":"poem-2581043a4978957dcd19a4ec","title":"鼓吹曲辞 鼓吹铙歌 靖本邦","author":"柳宗元","dynasty":"唐","verses":["本邦伊晋，惟时不靖。","根柢之摇，枝叶攸病。","守臣不任，勚于神圣。","惟钺之兴，翦焉则定。","洪惟我理，式和以敬。","群顽既夷，庶绩咸正。","皇谟载大，惟人之庆。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-7b0a825b-9e1e-4f34-b831-49ce8fd7f97c","tags":[]},{"id":"poem-2591680e509db8d6e53f4f87","title":"西江月·微步凌波尘起","author":"向子𬤇","dynasty":"宋","verses":["微步凌波尘起，弄妆满镜花开。","春心掷处眼频来。","秀色著人无耐。","旧事如风无迹，新愁似水难裁。","相思日夜梦阳台。","减尽沈郎衣带。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-783","tags":[]},{"id":"poem-2591eb885ff5263e010d929d","title":"僧乞示入藂林径直之路答以此颂（题拟）","author":"道怤","dynasty":"唐","verses":["我适抑不已，汝须不当急。","机竖尚亏投，影没大难及。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-52a63b16-4e1d-45b9-971f-63726c116459","tags":[]},{"id":"poem-25987a6909b310d01744db02","title":"自岭下泛鹢到清远峡作","author":"胡曾","dynasty":"唐","verses":["乘船浮鹢下韶水，绝境方知在岭南。","薜荔雨余山自黛，蒹葭烟尽岛如蓝。","旦游萧帝新松寺，夜宿嫦娥桂影潭。","不为箧中书未献，便来兹地结茅庵。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-5cd000a6-22f5-4b17-8fd7-7e4b2b27bc9c","tags":[]},{"id":"poem-259fe33644bac99d5b946acd","title":"风琴赠选上人","author":"释居简","dynasty":"宋","verses":["万籁甫消声，锵然忽自鸣。","独宜风力小，双与月华清。","历历谐三叠，玲玲叶九成。","宫商虽断续，何处不分明。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-494e5612-19dd-4e69-8b5f-6563d9ba6692","tags":[]},{"id":"poem-25adaba231f916089d8aded4","title":"秋闺  其三","author":"王同祖","dynasty":"宋","verses":["入秋情思可曾忺，深琐朱扉怯卷帘。","书几无人尘不扫，一钩蛛网挂牙签。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-a30ed948-773d-4af5-9fd8-4bc8beaac50c","tags":[]},{"id":"poem-25b1d6c947c2f52d42540d71","title":"蜘蛛讽","author":"孟郊","dynasty":"唐","verses":["万类皆有性，各各禀天和。","蚕身与汝身，汝身何太讹。","蚕身不为己，汝身不为佗。","蚕丝为衣裳，汝丝为网罗。","济物几无功，害物日已多。","百虫虽切恨，其将奈尔何。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-9a2c04d4-88ec-4029-ac1b-96a2c4d41a42","tags":[]},{"id":"poem-25b7c6589e7c302bf8b3c286","title":"朴翁约效诚斋分题得月色","author":"释居简","dynasty":"宋","verses":["霜晴如此月明何，独恨空庭著不多。","窗外楼头都有了，其余四散尽从它。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-030d4ed0-c715-4a66-b436-319bd742c244","tags":[]},{"id":"poem-25b8292367cb27da07db61b9","title":"酒罢张大彻索赠诗","author":"李贺","dynasty":"唐","verses":["长鬣张郎三十八，天遣裁诗花作骨。","往还谁是龙头人，公主遣秉鱼须笏。","太行青草上白衫，匣中章奏密如蚕。","金门石阁知卿有，豸角鸡香早晚含。","陇西长吉摧颓客，酒阑感觉中区窄。","葛衣断碎赵城秋，吟诗一夜东方白。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-317e061a-3b17-440f-8152-3fed3c0521e2","tags":[]},{"id":"poem-25bec16152bfde31f97e0899","title":"再次韵","author":"陈造","dynasty":"宋","verses":["归担乍弛谁洗泥，使君载酒携歌儿。","小家卷褥当酒负，醉倒一笑眠虎皮。","平生自审枯槁甚，高情顾肯振拂之。","均州从事六辈来，欢喜如官浴凤池。","诗筒偕拜府公赐，格律高古语崛奇。","头风失去肺渴减，病夫虽病容枝持。","南山侧望洁斋久，知我日诵无生诗。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-1dfc5f20-9370-43a2-9571-f557ea0a9920","tags":[]},{"id":"poem-25c1a9eb23ae19bd4714b842","title":"渐堂","author":"华镇","dynasty":"宋","verses":["君家仲季乐天长，书史优游共一堂。","雁序此时详进止，鸰原异日竟轩昂。","阶前兰菊幽香远，座上埙篪逸韵长。","肃穆清风在华榜，可令进躁坐销亡。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-a6418f68-70d7-4f00-975d-a4905b1cd2fb","tags":[]},{"id":"poem-25dc06ab0b28380b7e641ec3","title":"路中口号","author":"皇甫曾","dynasty":"唐","verses":["还乡不见家，年老眼多泪。","车马上河桥，城中好天气。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-aad0a00e-1871-44e1-ae2a-1a92eab081b4","tags":[]},{"id":"poem-25e6c7a2acb77e6f4e387a3b","title":"郊庙歌辞 武后大享昊天乐章 三","author":"不详","dynasty":"唐","verses":["干仪混成冲邃，天道下济高明。","闿阳晨披紫阙，太一晓降黄庭。","圆坛敢[申]昭报，方璧冀展虔情。","丹禁式敷衷恳，玄鉴庶察微诚。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-86f014f5-1e88-4a78-9efe-8e6b9f923c7a","tags":[]},{"id":"poem-25eb760466d1fdc2d323855f","title":"不了语","author":"雍裕之","dynasty":"唐","verses":["浮名世利知多少，朝市喧喧尘扰扰。","车马交驰往复来，钟鼓相催天又晓。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-400113e1-554d-4b53-9b8b-1bd1fb79f975","tags":[]},{"id":"poem-25ef74f4745f248b2388d655","title":"荷叶杯·记得那年花下","author":"韦庄","dynasty":"五代","verses":["记得那年花下，深夜，初识谢娘时。","水堂西面画帘垂，携手暗相期。","惆怅晓莺残月，相别，从此隔音尘。","如今俱是异乡人，相见更无因。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-44","tags":[]},{"id":"poem-25f825cf60417a5f2070cb28","title":"菩萨蛮 其二","author":"温庭筠","dynasty":"唐","verses":["水晶帘里玻璃枕，暖香惹梦鸳鸯锦。","江上柳如烟，雁飞残月天。","藕丝秋色浅，人胜参差剪。","双鬓隔香红，玉钗头上风。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-1","tags":[]},{"id":"poem-25f8f2d60a2c7eaf2cbca940","title":"巫山下作","author":"唐求","dynasty":"唐","verses":["细腰宫尽旧城摧，神女归山更不来。","唯有楚江斜日里，至今犹自绕阳台。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-f643e194-522c-4420-8fe8-7f0c0e96fc81","tags":[]},{"id":"poem-25fb1cf7e522f9557bd83e06","title":"春暮思平泉杂咏二十首 望伊川","author":"李德裕","dynasty":"唐","verses":["远村寒食后，细雨度川来。","芳草连谿合，梨花映墅开。","槿篱悬落照，松径长新苔。","向夕亭臯望，游禽几处回。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-7ca78c96-d703-4bc1-839c-3bc02f55bdf9","tags":[]},{"id":"poem-25fdd5c7ce6db0c2341cb5b2","title":"郊庙歌辞 雩祀乐章 肃和","author":"褚亮","dynasty":"唐","verses":["朱鸟开辰，苍龙启映。","大帝昭飨，群生展敬。","礼备怀柔，功宣舞咏。","旬液应序，年祥协庆。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-4d28776f-732f-41d4-bef1-52195b731076","tags":[]},{"id":"poem-2601c11eaed948a0d795f1ed","title":"豹子令","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["闻说佳人多袅娜，多袅娜，端的容貌赛嫦娥，赛嫦娥。","此亲若得周全我，酬劳财礼敢虚过。","［合］花红羊酒谢媒婆。","［丑］成亲之后，就是姑婆。","［净］朱吉，你牵羊担酒谢姑婆。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8065","tags":[]},{"id":"poem-2605cad89da3573b8e762273","title":"失调名·后会不知谁健","author":"詹克爱","dynasty":"宋","verses":["后会不知谁健，茱萸莫厌重看。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-314","tags":[]},{"id":"poem-2606ace1bca4f818fd0dbd7d","title":"唐多令·何处合成愁","author":"吴文英","dynasty":"宋","verses":["何处合成愁。","离人心上秋。","纵芭蕉、不雨也飕飕。","都道晚凉天气好，有明月、怕登楼。","年事梦中休。","花空烟水流。","燕辞归、客尚淹留。","垂柳不萦裙带住，漫长是、系行舟。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-86","tags":["宋词三百首"]},{"id":"poem-2606e56e569840f472399ed0","title":"次李泰发韵二首送仲辅提刑弟还浙东  其二","author":"李纲","dynasty":"宋","verses":["谒告来归若骏奔，友于真可裕礽晜。","共伤庭玉先埋土，怅望鸰原增断魂。","白髪自嗟临药灶，一瓶端欲寄空门。","浙东耆旧如相问，为道衰迟愧主恩。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-453e7989-b1e9-4ce6-a3e5-d88c77debfbb","tags":[]},{"id":"poem-261d297168d448c072ade4ad","title":"题林子默隠居","author":"林迥","dynasty":"宋","verses":["先生平昔命何非，万卷诗书一布衣。","回首长安成底事，吴山苍翠几时归。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-36a19d6e-f225-4dc1-a3c8-1e720c3a7c54","tags":[]},{"id":"poem-261df5fd962c58a45940928e","title":"对酒","author":"曹操","dynasty":"汉","verses":["对酒歌，太平时，吏不呼门。","王者贤且明，宰相股肱皆忠良。","咸礼让，民无所争讼。","三年耕有九年储，仓谷满盈。","斑白不负载。","雨泽如此，百谷用成。","却走马，以粪其土田。","爵公侯伯子男，咸爱其民，以黜陟幽明。","子养有若父与兄。","犯礼法，轻重随其刑。","路无拾遗之私。","囹圄空虚，冬节不断。","人耄耋，皆得以寿终。","恩德广及草木昆虫。"],"enabled":true,"collection":"曹操诗集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/曹操诗集/caocao.json#record-3","tags":[]},{"id":"poem-261f08fe16ee3e266c6cd496","title":"江南杂题三十首 其三","author":"张祜","dynasty":"唐","verses":["鸟逸溪云静，人行野岸稀。","茅峰三点翠，练水一条辉。","晚蝶花心少，阴莹草里微。","何妨孟朱舍，夜饮醉歌归。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-c17453f5-e2bf-455c-9dae-eaafe575c41f","tags":[]},{"id":"poem-26212fdf5f164711150e1f88","title":"题灵岩寺","author":"张祜","dynasty":"唐","verses":["北寺三年别，西湖十里程。","山门桥上转，石路阁中行。","地入千重险，江分一面平。","引藤闻鼠乱，窥洞见龙惊。","嶂月排簷出，屏风倚槛成。","猿寻青壁过，树遶碧崖生。","小殿灵云影，高廊下水声。","何当还梦谢，尽我一诗情。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-d7d635b2-178e-4e6a-8bce-8a4cab75e2fa","tags":["西湖"]},{"id":"poem-262381c19cf5bbac67f099ab","title":"漫书五首 四","author":"司空图","dynasty":"唐","verses":["世路快心无好事，恩门嘉话合书绅。","神藏鬼伏能千变，亦胜忘机避要津。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-4446a7e3-637f-4903-8e8a-ea3b5dfc335c","tags":[]},{"id":"poem-2625c3ee16a11e618b3e653d","title":"江城子·咏史","author":"纳兰性德","dynasty":"清","verses":["湿云全压数峰低。","影凄迷，望中疑。","非雾非烟，神女欲来时、若问生涯原是梦，除梦里，没人知。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-14","tags":[]},{"id":"poem-26276c41c301fe5409db55ba","title":"锦缠道","author":"施惠《幽闺记》","dynasty":"元","verses":["髻云堆，珠翠簇。","兰姿蕙质，香肌称罗绮。","黛眉长，盈盈照一泓秋水。","鞋直上冠儿至底。","诸余没半星儿不美。","针指暂闲时，花朝月夕，丫鬟侍妾随。","好景须欢会，四时不负佳致。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2895","tags":[]},{"id":"poem-262a98f4ab14b390e6ff05e6","title":"感兴临蕃驯雁","author":"佚名","dynasty":"唐","verses":["感兹驯雁色苍苍，徘徊顾步貌昂昂。","不见衔芦避缯缴，空闻落翮困堤塘。","差池为失衡（原作「冲」）阳伴，邂逅飘零虏塞傍。","引颈长鸣望云路，何时刷羽接归行。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-8ecd0d25-b3ab-462a-b7e7-680721620c5a","tags":[]},{"id":"poem-262ca1f63d064fc344b23a73","title":"诉衷情·东城南陌路歧斜","author":"晁补之","dynasty":"宋","verses":["东城南陌路歧斜。","芳草遍藏遮。","黄鹂自是来晚，莫恨海棠花。","惊雪絮，满天涯。","送春赊。","问春莫是，忆著东君，自去还家。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-138","tags":[]},{"id":"poem-265098912494aa552e29b4e5","title":"金陵凤凰台","author":"汪宗臣","dynasty":"宋","verses":["龙虎势称雄，凤凰台望浓。","潮翻江汉转，地扼楚淮冲。","平野频烽火，孤城半稑穜。","丹楹傍萧寺，尘扆识高宗。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-c7c978f4-20d0-49ee-8ce3-3265d64f587a","tags":[]},{"id":"poem-265d1ad16f41239e3bfa3472","title":"同官送鲈二首  其一","author":"米芾","dynasty":"宋","verses":["斑鳞拧鬣玉为肌，梦入松江自可疑。","𨁝跳金盘催脍手，西风正是忆鲈时。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-2d67734d-fd24-4175-a7e7-c638bc7e35d9","tags":[]},{"id":"poem-265eace9cfbab560e7bc10e6","title":"杂曲歌辞 金缕衣","author":"不详","dynasty":"唐","verses":["劝君莫惜金缕衣，劝君惜取少年时。","花开堪折直须折，莫待无花空折枝。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-a8617715-ad59-4da8-8071-e9aeb1760e6a","tags":["唐诗三百首","惜时","励志","乐府"]},{"id":"poem-265f0e10cd3ae8c31a726635","title":"杂兴","author":"聂夷中","dynasty":"唐","verses":["两叶能蔽目，双豆能塞聪。","理身不知道，将为天地聋。","扰扰造化内，茫茫天地中。","苟或有所愿，毛髪亦不容。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-8c867101-ade7-4ee6-b24b-d2eaa77eae09","tags":[]},{"id":"poem-266b4f6489c5a757cfbf4674","title":"秋入关","author":"贾驰","dynasty":"唐","verses":["河上微风来，关头树初湿。","今朝关城吏，又见孤客入。","上国谁与期，西来徒自急。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-3665e325-1fcd-40f3-961d-b7c7b68c4c33","tags":[]},{"id":"poem-26708cd3c0c3e966a6898e9b","title":"赠边将","author":"张乔","dynasty":"唐","verses":["将军夸胆气，功在杀人多。","对酒擎钟饮，临风拔劒歌。","翻师平碎叶，掠地取交河。","应笑孔门客，年年羡四科。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-6c9edfa3-cbb6-47b0-a637-e1cdc52e06f3","tags":[]},{"id":"poem-267e8ee2c86c85959e7d2779","title":"次韵汪汝冯见赠","author":"曾协","dynasty":"宋","verses":["身闲官冷巧相如，草舍柴扉况并居。","刮目尚为三日别，论心真胜十年书。","屡烦折简催羸马，知有新粧出绮疏。","兴发会须携短策，要看风味慰逃虚。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-34081d18-c79b-49a5-88ba-64b94ec0d68c","tags":[]},{"id":"poem-268355a88778ef6c9cbc03e6","title":"同王征君洞庭有怀","author":"张谓","dynasty":"唐","verses":["八月洞庭秋，潇湘水北流。","还家万里梦，为客五更愁。","不用开书帙，偏宜上酒楼。","故人京洛满，何日复同游。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-同王徵君洞庭有懷","tags":[]},{"id":"poem-2696fb6a23ebd3f104b77ff4","title":"晚秋登城之作 二","author":"佚名","dynasty":"唐","verses":["东山日色片光残，西岭云各暝草寒。","谷口穹庐遥逦迤，磎边牛马暮盘跚。","目前愁见川至窄，望处心迷兴不宽。","乡国未知何所在，路逢相识问看看。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-ced75eb6-a564-44db-b0e6-a4bbdffb7485","tags":[]},{"id":"poem-26990473782178f084202a42","title":"大漠行","author":"胡皓","dynasty":"唐","verses":["单于犯蓟堧，虏骑略萧边。","南山木叶飞下地，北海蓬根乱上天。","科斗连营太原道，鱼丽合阵武威川。","三军遥倚伏，万里相驰逐。","旌斾悠悠静潮源，鼙鼓喧喧动卢谷。","穷徼出幽陵，吁嗟倦寝兴。","马蹄冻溜石，胡毳煖生冰。","云沙泱漭天光闭，河塞阴沈海色凝。","崆峒北国谁能托，萧索边心常不乐。","近见行人畏白龙，遥闻公主愁黄鹤。","阳春半，岐路间，瑶台苑，玉门关。","百花芳树红将歇，二月兰臯绿未还。","阵云不散鱼龙水，雨雪犹飞鸿鹄山。","山嶂緜连那可极，路远辛勤梦颜色。","北堂萱草不寄来，东园桃李长相忆。","汉将纷纭攻战盈，胡寇萧条幽朔清。","韩昌拜节偏知送，郑吉驱旌坐见迎。","火绝烟沈左西极，谷静山空右北平。","但得将军能百胜，不须天子筑长城。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-a9fabab9-0c8d-42d4-bed2-1cb0ffd1305c","tags":[]},{"id":"poem-26a34646e3689f1ad53ab956","title":"山居诗  其六三","author":"释延寿","dynasty":"宋","verses":["清平大业行皆奢，岂独尧时听所加。","丰俭由人天不远，安危在智道非赊。","关津防害翻为害，法令除邪却长邪。","争似无言敷密化，既能成国又成家。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-90cdaad0-5f60-4d40-a142-bdaea1cd78a0","tags":[]},{"id":"poem-26b77ec43d2e6a434a38ef31","title":"暮春即事","author":"叶采","dynasty":"宋","verses":["双双瓦雀行书案，点点杨花入砚池。","闲坐小窗读周易，不知春去几多时。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-暮春即事","tags":[]},{"id":"poem-26c4df58d423d25b3bea13fd","title":"三棒鼓","author":"施惠《幽闺记》","dynasty":"元","verses":["(外王尚书、丑六儿引众上。","外)一鞭行色塑南京，喜得两国通和也无战争。","边疆罢征，边烽罢惊，不暂停。","(合)如今海晏河清也，重逢太平，重乐太平。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2992","tags":[]},{"id":"poem-26cc4c417508cd4ee1c82ff9","title":"稼穑","author":"汪宗臣","dynasty":"宋","verses":["稼穑病多雨，芜菁种待晴。","垒空惊燕去，池净衬鸥明。","野碓鸣秋杵，风簷响夜筝。","山中凉意早，蚊蚋已无声。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-0c476c01-5283-4989-899d-17a536afa5c7","tags":[]},{"id":"poem-26d8a2ecd4ca4dc65bc5c494","title":"句 二","author":"徐铉","dynasty":"唐","verses":["钟山祠畔宿烟晴，玉涧桥边碧树春。","（见《景定建康志》卷十八《山川志》。）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-f70d2979-1e74-4be4-b521-d42d265c4a99","tags":[]},{"id":"poem-26daa4a1c7b082049e7d7b5f","title":"十月初三四雪","author":"释居简","dynasty":"宋","verses":["霰集三秋后，花飞十月初。","更添两度白，并作一年书。","稻疃齐生耳，麰田烂弗鉏。","寒敲君子竹，压折怕林疎。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-0922897f-4cf1-4825-936b-b3cf2ba256e9","tags":[]},{"id":"poem-26e1ec2761586408e621a697","title":"郊庙歌辞 释奠文宣王乐章 承和","author":"不详","dynasty":"唐","verses":["万国以贞光上嗣，三善茂德表重轮。","视膳寝门尊要道，高辟崇贤引正人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-c8b5b494-9707-4004-8646-caf765ef20b8","tags":[]},{"id":"poem-26e3b8bf4041559844cac41f","title":"月夜怀刘秀才","author":"栖白","dynasty":"唐","verses":["独夜相思但自劳，阮生吟罢梦云涛。","此时小定未禅寂，古塔月中松磐高。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-da259365-e96a-44e9-a3eb-894785a24947","tags":[]},{"id":"poem-26e4596385b7ae6c39131e30","title":"越公上人洛中归寄南孟家兄弟","author":"李洞","dynasty":"唐","verses":["洛下因归去，官西忆二龙。","笠漫河岸雪，衣着虢城钟。","睡鸭浮寒水，樵人出远峰。","贺当化闾俗，护取草堂松。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-e0b8de07-28a5-44c2-8fb1-a70c701ba2a0","tags":[]},{"id":"poem-26e46cf151e947fca89ca614","title":"秋思","author":"鲍溶","dynasty":"唐","verses":["楚客秋更悲，皇皇无声地。","时无无事人，我命与身异。","良时如飞鸟，回掌成故事。","蹉跎秋定还，凝冽坚冰至。","人生不期老，华发谁能避。","感此惜壮年，壮年少为贵。","我生虽努力，荣途难自致。","徒为击角歌，且慙雕劒字。","吾师罕言命，感激潜伤思。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-9c82ce31-f228-41a1-a960-da4e36b95602","tags":[]},{"id":"poem-26e740065ec5e84cadad388a","title":"颂古十九首  其五","author":"释法全","dynasty":"宋","verses":["天高地厚寻常事，海阔山重更要论。","霹雳震摧山鬼窟，独携霜剑定乾坤。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-c78a91c0-a70d-4b8a-88ec-b184072a8f47","tags":[]},{"id":"poem-26e8626b8d1ed11ca98c402a","title":"临江仙·无赖晓莺惊梦断","author":"鹿虔扆","dynasty":"五代","verses":["无赖晓莺惊梦断，起来残醉初醒。","映窗丝柳袅烟青，翠帘慵卷，约砌杏花零。","一自玉郎游冶去，莲凋月惨仪形。","暮天微雨洒闲庭，手挼裙带，无语倚云屏。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-14","tags":[]},{"id":"poem-26eaeee888f9cfd71f6f562e","title":"追和贾浪仙古镜","author":"徐夤","dynasty":"唐","verses":["谁开黄帝桥山冢，明月飞光出九泉。","狼藉藓痕磨不尽，黑云残点污秋天。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-f91daa04-61f6-460c-9d58-2c986981ce9d","tags":[]},{"id":"poem-26f232dd8028373ec6cb6ec9","title":"菩萨蛮 其六","author":"温庭筠","dynasty":"唐","verses":["玉楼明月长相忆，柳丝袅娜春无力。","门外草萋萋，送君闻马嘶。","画罗金翡翠，香烛消成泪。","花落子规啼，绿窗残梦迷。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-5","tags":[]},{"id":"poem-26f3b48e2e961bf5d6a1f272","title":"奉和御制春雨","author":"徐铉","dynasty":"宋","verses":["祁祁甘雨正当春，草树精神一倍新。","匀洒农郊偏长麦，缓飘花槛不惊人。","密随宫仗环青辂，普逐皇恩下紫宸。","霁后楼台更堪望，满园桃李间松筠。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-438872df-5198-4c64-9196-889fa390dd06","tags":[]},{"id":"poem-26f69c5d808fa045003f4caa","title":"浣溪沙·转烛飘蓬一梦归","author":"李煜","dynasty":"五代","verses":["转烛飘蓬一梦归，欲寻陈迹怅人非。","天教心愿与身违。","待月池馆空逝水，映花楼阁谩斜晖。","登临不惜更沾衣。"],"enabled":true,"collection":"南唐二主词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/nantang/poetrys.json#record-43","tags":[]},{"id":"poem-2704801cde29f09130deed74","title":"满庭芳·瑟瑟金风","author":"向子𬤇","dynasty":"宋","verses":["瑟瑟金风，团团玉露，岩花秀发秋光。","水边一笑，十里得清香。","疑是蕊宫仙子，新妆就、娇额涂黄。","霜天晚，妖红丽紫，回首总堪伤。","中央。","孕正色，更留明月，偏照何妨。","便高如兰菊，也让芬芳。","输与芗林居士，微吟罢、闲据胡床。","须知道，天教尤物，相伴老江乡。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-997","tags":[]},{"id":"poem-270908a20bdba686e37d58d3","title":"横吹曲辞 前出塞九首 二","author":"杜甫","dynasty":"唐","verses":["出门日已远，不受徒旅欺。","骨肉恩岂断，男儿死无时。","走马脱辔头，手中挑青丝。","捷下万仞冈，俯身试搴旗。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-d572cc60-44fc-40c3-9c2f-08e966153fdd","tags":[]},{"id":"poem-270944712429f80721c2abb1","title":"过春秋峡","author":"刘言史","dynasty":"唐","verses":["峭壁苍苍苔色新，无风晴景自胜春。","不知何树幽崖里，腊月开花似北人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-60e1af46-66be-43d8-a2ad-94a12302cab2","tags":[]},{"id":"poem-27130131c0822172e89b1c5b","title":"石人峰","author":"缪岛云","dynasty":"唐","verses":["双峰何代列巍巍，忽化僊人世所稀。","绝顶长年相对坐，九天何日却同归。","风生松柏喧天乐，山隐云霞挂道衣。","终愿扪萝一相访，共君齐跨鳯鸾飞。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-2826f893-d4af-4160-8cf8-86b09e3660f2","tags":[]},{"id":"poem-272e188ce0068d37b7f78142","title":"望江南・忆江南·江上雪","author":"李纲","dynasty":"宋","verses":["江上雪，独立钓渔翁。","箬笠但闻冰散响，蓑衣时振玉花空。","图画若为工。","云水暮，归去远烟中。","茅舍竹篱依小屿，缩鳊圆鲫入轻笼。","欢笑有儿童。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-585","tags":[]},{"id":"poem-2730da44bb18478131d38e20","title":"登岳阳楼","author":"杜甫","dynasty":"唐","verses":["昔闻洞庭水，今上岳阳楼。","吴楚东南坼，乾坤日月浮。","亲朋无一字，老病有孤舟。","戎马关山北，凭轩涕泗流。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-登岳陽樓","tags":[]},{"id":"poem-273269f64f409b0efe21c835","title":"生查子·鞭影落春堤","author":"纳兰性德","dynasty":"清","verses":["鞭影落春堤，绿锦鄣泥卷。","脉脉逗菱丝，嫩水吴姬眼。","啮膝带香归，谁整樱桃宴。","蜡泪恼东风，旧垒眠新燕。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-41","tags":[]},{"id":"poem-2732b6a529e6966723ec18d3","title":"和人见寄","author":"綦崇礼","dynasty":"宋","verses":["江海同为客，山林不并居。","经时占喜鹊，今日剖双鱼。","拥鼻还成咏，撑肠未废书。","孤吟聊自遣，谁复借吹嘘。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-c9b9f52e-c414-4f02-8819-06effa4ba25a","tags":[]},{"id":"poem-273572a0d9256ef84a83752e","title":"进船泛洛水应制","author":"孙逖","dynasty":"唐","verses":["禁园纡睿览，仙櫂叶时游。","洛北风花树，江南彩画舟。","芳生兰蕙草，春入凤凰楼。","兴尽离宫暮，烟光起夕流。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-ff99e0d0-d60c-48e0-ac5c-38b24a0eeb30","tags":[]},{"id":"poem-273c2e6be3ebfec8f1c31156","title":"过钟陵","author":"李绅","dynasty":"唐","verses":["龙沙江尾抱钟陵，水郭村桥晚景澄。","江对楚山千里月，郭连渔浦万家灯。","省抛双斾辞荣宠，遽落丹霄起爱憎。","惆怅旧游同草露，却思恩顾一沾膺。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-1963d69d-9c2f-4385-8665-5c134cbeee92","tags":[]},{"id":"poem-273d73668b3c34d8c2d0b89b","title":"赠施肩吾","author":"张籍","dynasty":"唐","verses":["世间渐觉无多事，虽有空名未著身。","合取药成相待吃，不须先作上天人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-4ede77c0-4b3e-46d1-b196-bf7894fb10b9","tags":[]},{"id":"poem-273e9d35093b180335b2cede","title":"伐檀","author":"佚名","dynasty":"先秦","verses":["坎坎伐檀兮，置之河之干兮。河水清且涟猗。不稼不穑，胡取禾三百廛兮？","不狩不猎，胡瞻尔庭有县貆兮？彼君子兮，不素餐兮！","坎坎伐辐兮，置之河之侧兮。河水清且直猗。不稼不穑，胡取禾三百亿兮？","不狩不猎，胡瞻尔庭有县特兮？彼君子兮，不素食兮！","坎坎伐轮兮，置之河之漘兮。河水清且沦猗。不稼不穑，胡取禾三百囷兮？","不狩不猎，胡瞻尔庭有县鹑兮？彼君子兮，不素飧兮！"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-111","tags":[]},{"id":"poem-2744d5e77aa0172c763af629","title":"鹧鸪词二首 一","author":"李涉","dynasty":"唐","verses":["湘江烟水深，沙岸隔枫林。","何处鹧鸪飞，日斜斑竹阴。","二女空垂泪，三闾枉自沉。","惟有鹧鸪啼，独伤行客心。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-c71c6d07-b995-45d0-8a4c-6e52d666025b","tags":[]},{"id":"poem-2749ac34207e58c6b09b5c87","title":"观山水障子","author":"伍乔","dynasty":"宋","verses":["功绩精妍世少伦，图时应倍用心神。","不知草木承何异，但见江山长带春。","云势似离岩底石，浪花如动岸边苹。","更疑独泛渔舟者，便是其中旧隠人。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-eadf400c-75c9-4736-8b37-4ad04fd92fdc","tags":[]},{"id":"poem-27705afb44432b0034e109cc","title":"劝人 十三","author":"义存","dynasty":"唐","verses":["世中（《祖堂集》卷七作「间」）有一事，奉劝学者取。","虽无半钱活，流传历劫富。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-5841f3ab-791c-4be4-a2b9-bc6a52561558","tags":[]},{"id":"poem-2772de5184ec6fe8e1938892","title":"使至三姓咽面","author":"张宣明","dynasty":"唐","verses":["昔闻班家子，笔砚忽然投。","一朝抚长劒，万里入荒陬。","岂不服艰险，只思清国讐。","山川去何岁，霜露几逢秋。","玉塞已遐廓，铁关方阻修。","东都日窅窅，西海此悠悠。","卒使功名建，长封万里侯。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-caf76db9-d31b-429e-b8f4-4364e68e8014","tags":[]},{"id":"poem-2772fa530e33281d33667d4a","title":"和韦开州盛山十二首 竹岩","author":"张籍","dynasty":"唐","verses":["独入千竿里，缘岩踏石层。","笋头齐欲出，更不许人登。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-389039e4-0124-42c5-84cf-cf29ebcb31e4","tags":[]},{"id":"poem-2777ce37c84354ebf07b1999","title":"前腔换头","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["我爹爹，全不怕，人笑呵，这其间只是见差。","祸根芽，从此起，灾来怎躲？他只道我从着夫言，骂我不听亲话。","(生唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5180","tags":[]},{"id":"poem-27a0110a39618b1632ea8d38","title":"河满子·写得鱼笺无限","author":"和凝","dynasty":"五代","verses":["写得鱼笺无限，其如花锁春晖。","目断巫山云雨，空教残梦依依。","却爱熏香小鸭，羡他长在屏帷。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-21","tags":[]},{"id":"poem-27b6c859893ae999d6552fdf","title":"和韦兄春日南亭宴兄弟","author":"孙逖","dynasty":"唐","verses":["台阁升高位，园林隔旧乡。","忽闻歌棣萼，还比报琼芳。","门向宜春近，郊连御宿长。","德星常有会，相望在文昌。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-d8cd2910-f2b2-45b6-8ff3-727e7e416b21","tags":[]},{"id":"poem-27bc24e5af5875679629de8d","title":"临江仙·向日鹓行瞻凤彩","author":"洪适","dynasty":"宋","verses":["向日鹓行瞻凤彩，共期直上金銮。","却来持节海云边。","身兼三使者，名是一仙官。","汉室中兴高密冠，千年苗裔蝉联。","左弧嘉庆舞祥烟。","橘中招四老，同醉酒如泉。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-698","tags":[]},{"id":"poem-27c2d55265205d47ad6e2b6b","title":"鹧鸪天·云到春飞若素期","author":"韩淲","dynasty":"宋","verses":["云到春飞若素期。","柳条吹送落梅枝。","冰壶表里谁能赋，玉鉴圆明且屈卮。","村舍北，郡楼西。","治中风调只心知。","不堪野老关门醉，想见山翁倒载时。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-482","tags":[]},{"id":"poem-27cedf79fc28b2ca3f7280a5","title":"都梁十景诗 龟山寺晚钟","author":"米芾","dynasty":"宋","verses":["龟峰高耸接云楼，撞月钟声吼铁牛。","一百八声俱听彻，夜行犹自不知休。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-549e4293-6aad-4f60-9d6d-05a88ee5be18","tags":[]},{"id":"poem-27d3f288a6b97d5639d6ed5e","title":"哭陆处士","author":"皇甫曾","dynasty":"唐","verses":["从此无期见，柴门对雪开。","二毛逢世难，万恨掩泉台。","返照空堂夕，孤城吊客回。","汉家偏访道，犹畏鹤书来。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-e8cc31e9-6b51-4a37-818b-7891dfb9677c","tags":[]},{"id":"poem-27d5161e9747746a367be89d","title":"晓发佛潭桥","author":"陈元光","dynasty":"唐","verses":["朝暾催上道，兔魄欲西沈。","去雁长空没，飞花曲径深。","事沿桥树往，诗落海鸥吟。","马鬣嘶风耸，龙旗闪电临。","峰攒仙掌巧，露重将袍阴。","农唤耕春早，僧迎展拜钦。","看看葵日丽，照破艳阳心。","（以上二诗见沈定均《漳州府志·艺文志》）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-736276bd-a0a1-4beb-8838-284b41d5bd99","tags":[]},{"id":"poem-27df09b9e225c41e3ca8732e","title":"送穆寂赴举","author":"皎然","dynasty":"唐","verses":["天子锡玄𫄸，倾山礼隐沦。","君抛青霞去，荣资观国宾。","劒光既陆离，琼彩何璘玢。","夙驾别情远，商弦秋意新。","冥冥鸿鹄姿，数尺看苍旻。","残寇近宋郊，西行恶飙尘。","立身素耿介，处难思经纶。","春府搜才日，高科得一人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-33cf667a-649b-4f76-9009-48b6172cf325","tags":[]},{"id":"poem-27e0b8211c87652deb8d697b","title":"戏赠友人","author":"杨凝","dynasty":"唐","verses":["湘阴直与地阴连，此日相逢忆醉年。","美酒非如平乐贵，十升不用一千钱。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-00701b63-8026-4375-bb72-1163b291e5e3","tags":[]},{"id":"poem-27e42eb1e73519f53f395387","title":"句","author":"张为","dynasty":"唐","verses":["到处即闭户，逢君方展眉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-98ae2afc-2ec3-4fbf-8561-78d373464a45","tags":[]},{"id":"poem-27e4411e59879889b9cbfbc1","title":"费家风次韵二首  其二","author":"刘跂","dynasty":"宋","verses":["风雷助神物，兹理古不空。","邂逅一夕事，知有费家风。","洛桥诵书女，泾川牧羊童。","不知费氏子，业力与谁同。","便能役蜚廉，颇复鼓丰隆。","坐令城郭人，在尔动用中。","剑出延平水，竹化葛陂翁。","况尔得人趣，变现岂易穷。","时时要雨泽，袢暑殊未终。","勿逢金翅王，非尔能长雄。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-28923a75-2dc5-41b6-b402-01a05499a2ee","tags":[]},{"id":"poem-27e7c1941c2ebf1e72fadeef","title":"送韦八少府判官归东京","author":"崔峒","dynasty":"唐","verses":["玄成世业紫真官，文似相如貌胜潘。","鸿鴈南飞人独去，云山一别岁将阑。","清淮水急桑林晚，古驿霜多柿叶寒。","琼树相思何日见，银钩数字莫为难。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-a7066599-38bd-4570-b61a-ac733327440f","tags":[]},{"id":"poem-27f610259fbd5f19ce878b69","title":"七谏·怨世","author":"东方朔","dynasty":"汉","verses":["世沉淖而难论兮，俗岒峨而㟥嵯。","清泠泠而歼灭兮，溷湛湛而日多。","枭鸮既以成群兮，玄鹤弭翼而屏移。","蓬艾亲入御于床笫兮，马兰踸踔而日加。","弃捐药芷与杜衡兮，余柰世之不知芳何？","何周道之平易兮，然芜秽而险戏。","高阳无故而委尘兮，唐虞点灼而毁议。","谁使正其真是兮，虽有八师而不可为。","皇天保其高兮，后土持其久。","服清白以逍遥兮，偏与乎玄英异色。","西施媞媞而不得见兮，嫫母勃屑而日侍。","桂蠹不知所淹留兮，蓼虫不知徙乎葵菜。","处湣湣之浊世兮，今安所达乎吾志。","意有所载而远逝兮，固非众人之所识。","骥踌躇于弊輂兮，遇孙阳而得代。","吕望穷困而不聊生兮，遭周文而舒志。","宁戚饭牛而商歌兮，桓公闻而弗置。","路室女之方桑兮，孔子过之以自侍。","吾独乖剌而无当兮，心悼怵而耄思。","思比干之恲恲兮，哀子胥之慎事。","悲楚人之和氏兮，献宝玉以为石。","遇厉武之不察兮，羌两足以毕斮。","小人之居势兮，视忠正之何若？","改前圣之法度兮，喜嗫嚅而妄作。","亲谗谀而疏贤圣兮，讼谓闾娵为丑恶。","愉近习而蔽远兮，孰知察其黑白？","卒不得效其心容兮，安眇眇而无所归薄。","专精爽以自明兮，晦冥冥而壅蔽。","年既已过太半兮，然埳轲而留滞。","欲高飞而远集兮，恐离罔而灭败。","独冤抑而无极兮，伤精神而寿夭。","皇天既不纯命兮，余生终无所依。","愿自沉于江流兮，绝横流而径逝。","宁为江海之泥涂兮，安能久见此浊世？"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-32","tags":[]},{"id":"poem-27fa9d2a6918a8256f78f879","title":"及第后读书院咏物[一]十首上礼部李侍郎 □□（伯三四八○）","author":"樊铸","dynasty":"唐","verses":["铸剑本来杀雠[一]人，怀珠本来报国士。","信知善恶皆相报，如何不肯树桃李。","物情飜覆难可论，莫言权势长头[二]存。","鼎食却为农桑子，布衣还启丞相门。","丈夫立身须自省，知祸知福如形影。","乍可惠人一饭恩，不得唾人千里井。","（[一]原作「雠杀」，依刘校互乙。","[二]刘云：「『长头』二字乃俗语。","『头』，尾声。","」）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-c5b4a22d-9d2b-466a-984f-4542b7b87aeb","tags":[]},{"id":"poem-28002f0ce54c7ba378574929","title":"酬举生许遇山居","author":"李涉","dynasty":"唐","verses":["琉璃潭上新秋月，清净泉中智惠珠。","不似本宗疎二教，许过云壑访潜夫。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-e5004c92-9fba-4ea7-9882-434de508dd65","tags":[]},{"id":"poem-2804d24de4f16a71d5088ef8","title":"牧童","author":"卢肇","dynasty":"唐","verses":["谁人得似牧童心，牛上横眠秋听深。","时复往来吹一曲，何愁南北不知音。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-65e7bb97-8b44-486d-9046-9a575f9ec7a7","tags":[]},{"id":"poem-280a469239219af7151da15e","title":"送友人归江南","author":"聂夷中","dynasty":"唐","verses":["皇州五更鼓，月落西南维。","此时有行客，别我孤舟归。","上国身无主，下第诚可悲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-75e09623-9ab1-4f2f-8d40-0888d8bd88f1","tags":[]},{"id":"poem-280c33c06678daff0724d38c","title":"烝民","author":"佚名","dynasty":"先秦","verses":["天生烝民，有物有则。民之秉彝，好是懿德。天监有周，昭假于下。保兹天子，生仲山甫。","仲山甫之德，柔嘉维则。令仪令色。小心翼翼。古训是式。威仪是力。天子是若，明命使赋。","王命仲山甫，式是百辟，缵戎祖考，王躬是保。出纳王命，王之喉舌。赋政于外，四方爰发。","肃肃王命，仲山甫将之。邦国若否，仲山甫明之。既明且哲，以保其身。夙夜匪解，以事一人。","人亦有言，柔则茹之，刚则吐之。维仲山甫，柔亦不茹，刚亦不吐。不侮矜寡，不畏强御。","人亦有言，德𬨎如毛，民鲜克举之。我仪图之，维仲山甫举之。爱莫助之。衮职有阙，维仲山甫补之。","仲山甫出祖。四牡业业。征夫捷捷，每怀靡及。四牡彭彭，八鸾锵锵。王命仲山甫，城彼东方。","四牡骙骙，八鸾喈喈。仲山甫徂齐，式遄其归。吉甫作诵，穆如清风。仲山甫永怀，以慰其心。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-259","tags":[]},{"id":"poem-281bc3e8257c853a77ff87a2","title":"忆少年·无穷官柳","author":"晁补之","dynasty":"宋","verses":["无穷官柳，无情画舸，无根行客。","南山尚相送，只高城人隔。","罨画园林溪绀碧。","算重来、尽成陈迹。","刘郎鬓如此，况桃花颜色。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-221","tags":["宋词三百首"]},{"id":"poem-281f7e4b09ea67d7cdfe3201","title":"杂诗","author":"李端","dynasty":"唐","verses":["主第辞高饮，石家赴宵会。","金谷走车来，玉人骑马待。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-889c97a7-a749-41f9-8441-2001b4b60fa9","tags":[]},{"id":"poem-28239539173909c5f515aaac","title":"送友人下第归襄阳","author":"项斯","dynasty":"唐","verses":["失意已春残，归愁与别难。","山分关路细，江遶夜城寒。","草色连晴坂，鼍声离晓滩。","差池是秋赋，何以暂怀安。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-1683147a-c311-4559-a028-df40e7550af7","tags":[]},{"id":"poem-2826a06355b528c7c095451e","title":"句","author":"李子迁","dynasty":"宋","verses":["石鼎夜联诗笔健，布囊春醉酒钱粗。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-82081573-d240-4519-8d2b-264ad133a10f","tags":[]},{"id":"poem-28277076f08192128b6252fa","title":"北青萝","author":"李商隐","dynasty":"唐","verses":["残阳西入崦，茅屋访孤僧。","落叶人何在，寒云路几层。","独敲初夜磬，闲倚一枝藤。","世界微尘里，吾宁爱与憎。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-9380d4f6-e19d-4ff1-8309-07f4ede69f7c","tags":["唐诗三百首","寻访","五言律诗"]},{"id":"poem-282b56bfee18bba72eca8bc9","title":"筹笔店江亭","author":"陆畅","dynasty":"唐","verses":["九折岩边下马行，江亭暂歇听江声。","白云绿树不关我，枉与樵人乐一生。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-6df1bb17-4bab-4729-9a5b-14387ba68788","tags":[]},{"id":"poem-282c54049579d681b7d48387","title":"神功盛德诗  其一七","author":"华镇","dynasty":"宋","verses":["俾尔息而庶，俾尔厚而富。","黄发稚齿，既仁且寿。","帝歆其馨，介我纯祐。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-4854dfdb-338d-4451-84d8-1e644ffc554f","tags":[]},{"id":"poem-2833b40d9dcec4a8a75d5cbb","title":"浣溪沙·征雁年来得几回","author":"王质","dynasty":"宋","verses":["征雁年来得几回。","春风无雁带书归。","故应春瘦减春衣。","花柳伤心经岁月，江湖无梦失津涯。","到家无树不红飞。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-312","tags":[]},{"id":"poem-2839c3f7c8f89fa7facb7edc","title":"瑞鹤仙·郊原初过雨","author":"袁去华","dynasty":"宋","verses":["郊原初过雨。","见败叶零乱，风定犹舞。","斜阳挂深树。","映浓愁浅黛，遥山眉妩。","来时旧路。","尚岩花、娇黄半吐。","到而今，唯有溪边流水，见人如故。","无语。","邮亭深静，下马还寻，旧曾题处。","无聊倦旅。","伤离恨，最愁苦。","纵收香藏镜，他年重到，人面桃花在否。","念沈沈、小阁幽窗，有时梦去。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-10","tags":["宋词三百首"]},{"id":"poem-283b3a0a7d9deb9dfbbfe42f","title":"哭亦周  其三","author":"赵文","dynasty":"宋","verses":["擢第君王与袍笏，盖棺丞相办深衣。","江南仕宦堪车载，如此全归似汝稀。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-7b3b690e-8135-48cb-a3ba-ddf943cbde1f","tags":[]}];
